//! Netmaker adapter — bridges Netmaker HTTP REST API to gRPC.
//! Connects via unix socket: /run/netmaker/api.sock

use crate::proto::{
    netmaker_service_server::NetmakerService, ExecuteCommandRequest, ExecuteCommandResponse,
    GetNetworkRequest, GetNetworkResponse, GetNodeRequest, GetNodeResponse, HealthRequest,
    HealthResponse, Host, JoinNetworkRequest, JoinNetworkResponse, LeaveNetworkRequest,
    LeaveNetworkResponse, ListHostsRequest, ListHostsResponse, ListNetworksRequest,
    ListNetworksResponse, ListNodesRequest, ListNodesResponse, NetmakerEvent, Network, Node,
    RestartServiceRequest, RestartServiceResponse, StreamEventsRequest,
};
use async_trait::async_trait;
use serde_json::Value as JsonValue;
use std::pin::Pin;
use tokio::process::Command;
use tokio_stream::Stream;
use tonic::{Request, Response, Status};

#[allow(dead_code)]
const API_SOCK: &str = "/run/netmaker/api.sock";

pub struct NetmakerAdapter {
    client: reqwest::Client,
    #[allow(dead_code)]
    base_url: String,
}

impl NetmakerAdapter {
    pub fn new() -> Self {
        // Route HTTP through the service endpoint exposed by the socket-backed
        // registration path.
        let client = reqwest::Client::builder().build().expect("reqwest client");
        Self {
            client,
            base_url: "http://localhost".to_string(),
        }
    }

    async fn get<T: serde::de::DeserializeOwned>(&self, path: &str) -> Result<T, Status> {
        let master_key =
            std::env::var("NETMAKER_MASTER_KEY").unwrap_or_else(|_| "masterkey".to_string());

        // The socket-backed registration path resolves the service endpoint;
        // the adapter keeps a conventional HTTP client here.
        let url = format!("http://127.0.0.1:8081{}", path);
        let resp = self
            .client
            .get(&url)
            .header("Authorization", format!("Bearer {}", master_key))
            .send()
            .await
            .map_err(|e| Status::unavailable(format!("Netmaker API unavailable: {}", e)))?;

        if !resp.status().is_success() {
            return Err(Status::internal(format!(
                "Netmaker API error: {}",
                resp.status()
            )));
        }

        resp.json::<T>()
            .await
            .map_err(|e| Status::internal(format!("Netmaker API parse error: {}", e)))
    }

    async fn patch_netclient_config<F>(&self, edit: F) -> Result<(), Status>
    where
        F: FnOnce(&mut JsonValue),
    {
        let path = "/etc/netclient/netclient.json";
        let mut config = match tokio::fs::read_to_string(path).await {
            Ok(content) => serde_json::from_str::<JsonValue>(&content)
                .map_err(|e| Status::internal(format!("netclient config parse error: {}", e)))?,
            Err(_) => serde_json::json!({}),
        };

        edit(&mut config);

        tokio::fs::create_dir_all("/etc/netclient")
            .await
            .map_err(|e| Status::internal(format!("netclient config dir error: {}", e)))?;
        tokio::fs::write(
            path,
            serde_json::to_string_pretty(&config).unwrap_or_else(|_| "{}".to_string()),
        )
        .await
        .map_err(|e| Status::internal(format!("netclient config write error: {}", e)))?;
        Ok(())
    }

    async fn restart_netclient(&self) -> Result<(), Status> {
        let resp = self
            .execute_command(Request::new(ExecuteCommandRequest {
                command: Some(crate::proto::execute_command_request::Command::Restart(
                    RestartServiceRequest {
                        service: "netclient".to_string(),
                    },
                )),
            }))
            .await?
            .into_inner();
        if resp.success {
            Ok(())
        } else {
            Err(Status::internal(resp.stderr))
        }
    }
}

impl Default for NetmakerAdapter {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl NetmakerService for NetmakerAdapter {
    async fn get_server_health(
        &self,
        _req: Request<HealthRequest>,
    ) -> Result<Response<HealthResponse>, Status> {
        #[derive(serde::Deserialize)]
        struct HealthResp {
            status: String,
            version: Option<String>,
        }
        let r: HealthResp = self.get("/api/server/health").await?;
        Ok(Response::new(HealthResponse {
            status: r.status,
            version: r.version.unwrap_or_default(),
        }))
    }

    async fn list_networks(
        &self,
        _req: Request<ListNetworksRequest>,
    ) -> Result<Response<ListNetworksResponse>, Status> {
        #[derive(serde::Deserialize)]
        struct Net {
            netid: String,
            addressrange: Option<String>,
            addressrange6: Option<String>,
            localrange: Option<String>,
        }
        let nets: Vec<Net> = self.get("/api/networks").await?;
        let networks = nets
            .into_iter()
            .map(|n| Network {
                name: n.netid,
                address_range: n.addressrange.unwrap_or_default(),
                address_range6: n.addressrange6.unwrap_or_default(),
                is_local: n.localrange.is_some(),
            })
            .collect();
        Ok(Response::new(ListNetworksResponse { networks }))
    }

    async fn get_network(
        &self,
        req: Request<GetNetworkRequest>,
    ) -> Result<Response<GetNetworkResponse>, Status> {
        #[derive(serde::Deserialize)]
        struct Net {
            netid: String,
            addressrange: Option<String>,
            addressrange6: Option<String>,
            localrange: Option<String>,
        }
        let n: Net = self
            .get(&format!("/api/networks/{}", req.into_inner().name))
            .await?;
        Ok(Response::new(GetNetworkResponse {
            network: Some(Network {
                name: n.netid,
                address_range: n.addressrange.unwrap_or_default(),
                address_range6: n.addressrange6.unwrap_or_default(),
                is_local: n.localrange.is_some(),
            }),
        }))
    }

    async fn list_nodes(
        &self,
        req: Request<ListNodesRequest>,
    ) -> Result<Response<ListNodesResponse>, Status> {
        #[derive(serde::Deserialize)]
        struct N {
            id: String,
            name: Option<String>,
            address: Option<String>,
            publickey: Option<String>,
            connected: Option<bool>,
            lastcheckin: Option<i64>,
        }
        let network = req.into_inner().network;
        let path = if network.is_empty() {
            "/api/nodes".to_string()
        } else {
            format!("/api/nodes/{}", network)
        };
        let raw: Vec<N> = self.get(&path).await?;
        let nodes = raw
            .into_iter()
            .map(|n| Node {
                id: n.id,
                name: n.name.unwrap_or_default(),
                address: n.address.unwrap_or_default(),
                public_key: n.publickey.unwrap_or_default(),
                connected: n.connected.unwrap_or(false),
                last_checkin: n.lastcheckin.map(|t| t.to_string()).unwrap_or_default(),
            })
            .collect();
        Ok(Response::new(ListNodesResponse { nodes }))
    }

    async fn get_node(
        &self,
        req: Request<GetNodeRequest>,
    ) -> Result<Response<GetNodeResponse>, Status> {
        #[derive(serde::Deserialize)]
        struct N {
            id: String,
            name: Option<String>,
            address: Option<String>,
            publickey: Option<String>,
            connected: Option<bool>,
            lastcheckin: Option<i64>,
        }
        let n: N = self
            .get(&format!("/api/nodes/{}", req.into_inner().id))
            .await?;
        Ok(Response::new(GetNodeResponse {
            node: Some(Node {
                id: n.id,
                name: n.name.unwrap_or_default(),
                address: n.address.unwrap_or_default(),
                public_key: n.publickey.unwrap_or_default(),
                connected: n.connected.unwrap_or(false),
                last_checkin: n.lastcheckin.map(|t| t.to_string()).unwrap_or_default(),
            }),
        }))
    }

    async fn list_hosts(
        &self,
        _req: Request<ListHostsRequest>,
    ) -> Result<Response<ListHostsResponse>, Status> {
        #[derive(serde::Deserialize)]
        struct H {
            id: String,
            name: Option<String>,
            publickey: Option<String>,
            version: Option<String>,
        }
        let raw: Vec<H> = self.get("/api/hosts").await?;
        let hosts = raw
            .into_iter()
            .map(|h| Host {
                id: h.id,
                name: h.name.unwrap_or_default(),
                public_key: h.publickey.unwrap_or_default(),
                version: h.version.unwrap_or_default(),
            })
            .collect();
        Ok(Response::new(ListHostsResponse { hosts }))
    }

    async fn join_network(
        &self,
        req: Request<JoinNetworkRequest>,
    ) -> Result<Response<JoinNetworkResponse>, Status> {
        let r = req.into_inner();
        self.patch_netclient_config(|config| {
            config["enabled"] = serde_json::json!(true);
            config["default_network"] = serde_json::json!(r.network);
            config["enrollment_token"] = serde_json::json!(r.token);
            config["interface"] = serde_json::json!("netmaker");
            config["inittype"] = serde_json::json!(6);
        })
        .await?;
        self.restart_netclient().await?;
        Ok(Response::new(JoinNetworkResponse {
            success: true,
            message: "netclient configuration updated and restarted".to_string(),
        }))
    }

    async fn leave_network(
        &self,
        req: Request<LeaveNetworkRequest>,
    ) -> Result<Response<LeaveNetworkResponse>, Status> {
        let network = req.into_inner().network;
        self.patch_netclient_config(|config| {
            if config.get("default_network").and_then(|v| v.as_str()) == Some(network.as_str()) {
                config["default_network"] = serde_json::json!("");
            }
            config["enabled"] = serde_json::json!(false);
            config["enrollment_token"] = serde_json::json!(null);
        })
        .await?;
        self.restart_netclient().await?;
        Ok(Response::new(LeaveNetworkResponse {
            success: true,
            message: "netclient configuration updated and restarted".to_string(),
        }))
    }

    async fn restart_service(
        &self,
        req: Request<RestartServiceRequest>,
    ) -> Result<Response<RestartServiceResponse>, Status> {
        let service = req.into_inner().service;
        if service == "netclient" {
            self.restart_netclient().await?;
        } else {
            return Err(Status::invalid_argument(format!(
                "unsupported service '{}'",
                service
            )));
        }
        Ok(Response::new(RestartServiceResponse {
            success: true,
            message: format!("{} restarted", service),
        }))
    }

    async fn execute_command(
        &self,
        req: Request<ExecuteCommandRequest>,
    ) -> Result<Response<ExecuteCommandResponse>, Status> {
        let command = req.into_inner().command.ok_or_else(|| {
            Status::invalid_argument("missing command variant for netclient execution")
        })?;

        match command {
            crate::proto::execute_command_request::Command::Join(join) => {
                self.patch_netclient_config(|config| {
                    config["enabled"] = serde_json::json!(true);
                    config["default_network"] = serde_json::json!(join.network);
                    config["enrollment_token"] = serde_json::json!(join.token);
                    config["interface"] = serde_json::json!("netmaker");
                    config["inittype"] = serde_json::json!(6);
                })
                .await?;
                self.restart_netclient().await?;
                Ok(Response::new(ExecuteCommandResponse {
                    success: true,
                    exit_code: 0,
                    stdout: "joined network".to_string(),
                    stderr: String::new(),
                }))
            }
            crate::proto::execute_command_request::Command::Leave(leave) => {
                self.patch_netclient_config(|config| {
                    if config.get("default_network").and_then(|v| v.as_str())
                        == Some(leave.network.as_str())
                    {
                        config["default_network"] = serde_json::json!("");
                    }
                    config["enabled"] = serde_json::json!(false);
                    config["enrollment_token"] = serde_json::json!(null);
                })
                .await?;
                self.restart_netclient().await?;
                Ok(Response::new(ExecuteCommandResponse {
                    success: true,
                    exit_code: 0,
                    stdout: "left network".to_string(),
                    stderr: String::new(),
                }))
            }
            crate::proto::execute_command_request::Command::Restart(restart) => {
                if restart.service != "netclient" {
                    return Err(Status::invalid_argument(format!(
                        "unsupported service '{}'",
                        restart.service
                    )));
                }
                let output = Command::new(op_core::runit::SV_BIN)
                    .args(["restart", "netclient"])
                    .output()
                    .await
                    .map_err(|e| Status::internal(format!("failed to execute sv: {}", e)))?;
                Ok(Response::new(ExecuteCommandResponse {
                    success: output.status.success(),
                    exit_code: output.status.code().unwrap_or(-1),
                    stdout: String::from_utf8_lossy(&output.stdout).to_string(),
                    stderr: String::from_utf8_lossy(&output.stderr).to_string(),
                }))
            }
            crate::proto::execute_command_request::Command::Connect(req) => {
                self.run_command("connect", vec![req.network]).await
            }
            crate::proto::execute_command_request::Command::Disconnect(req) => {
                self.run_command("disconnect", vec![req.network]).await
            }
            crate::proto::execute_command_request::Command::List(_) => {
                self.run_command("list", vec![]).await
            }
            crate::proto::execute_command_request::Command::Peers(_) => {
                self.run_command("peers", vec![]).await
            }
            crate::proto::execute_command_request::Command::Ping(req) => {
                self.run_command("ping", vec![req.peer]).await
            }
            crate::proto::execute_command_request::Command::Pull(_) => {
                self.run_command("pull", vec![]).await
            }
            crate::proto::execute_command_request::Command::Push(_) => {
                self.run_command("push", vec![]).await
            }
            crate::proto::execute_command_request::Command::Register(req) => {
                self.run_command("register", vec![req.instance]).await
            }
            crate::proto::execute_command_request::Command::Server(req) => {
                let mut args = vec![req.subcommand];
                args.extend(req.args);
                self.run_command("server", args).await
            }
            crate::proto::execute_command_request::Command::Install(_) => {
                self.run_command("install", vec![]).await
            }
            crate::proto::execute_command_request::Command::Uninstall(_) => {
                self.run_command("uninstall", vec![]).await
            }
            crate::proto::execute_command_request::Command::Use(req) => {
                self.run_command("use", vec![req.version]).await
            }
            crate::proto::execute_command_request::Command::Version(_) => {
                self.run_command("version", vec![]).await
            }
        }
    }

    type StreamEventsStream = Pin<Box<dyn Stream<Item = Result<NetmakerEvent, Status>> + Send>>;

    async fn stream_events(
        &self,
        _req: Request<StreamEventsRequest>,
    ) -> Result<Response<Self::StreamEventsStream>, Status> {
        // Poll Netmaker's metric endpoint as a simple event stream
        let stream = async_stream::stream! {
            loop {
                tokio::time::sleep(tokio::time::Duration::from_secs(30)).await;
                yield Ok(NetmakerEvent {
                    event_type: "heartbeat".to_string(),
                    payload_json: "{}".to_string(),
                });
            }
        };
        Ok(Response::new(Box::pin(stream)))
    }
}

impl NetmakerAdapter {
    async fn run_command(
        &self,
        name: &str,
        args: Vec<String>,
    ) -> Result<Response<ExecuteCommandResponse>, Status> {
        let mut cmd = Command::new("netclient");
        cmd.arg(name);
        for arg in args {
            cmd.arg(arg);
        }
        let output = cmd
            .output()
            .await
            .map_err(|e| Status::internal(format!("failed to execute netclient: {}", e)))?;
        Ok(Response::new(ExecuteCommandResponse {
            success: output.status.success(),
            exit_code: output.status.code().unwrap_or(-1),
            stdout: String::from_utf8_lossy(&output.stdout).to_string(),
            stderr: String::from_utf8_lossy(&output.stderr).to_string(),
        }))
    }
}

//! gRPC Client - For D-Bus → remote gRPC calls
//!
//! Allows local D-Bus services to call remote gRPC endpoints,
//! enabling distributed operation-dbus deployments.

use std::collections::HashMap;
use std::sync::Arc;
use std::time::Duration;

use prost_types::{value::Kind as ProstKind, Struct as ProstStruct, Value as ProstValue};
use tokio::sync::RwLock;
use tonic::metadata::MetadataValue;
use tonic::transport::{Channel, Endpoint};
use tonic::Request;
use tracing::info;

use crate::proto::{
    event_chain_service_client::EventChainServiceClient,
    plugin_service_client::PluginServiceClient, state_sync_client::StateSyncClient,
    CallMethodRequest, GetStateRequest, MutateRequest, OperationType as ProtoOperationType,
    SubscribeEventsRequest, SubscribeRequest,
};
use op_grpc_adapters::proto::{
    execute_command_request::Command as ExecuteNetclientCommand,
    netmaker_service_client::NetmakerServiceClient, ConnectRequest, DisconnectRequest,
    ExecuteCommandRequest, ExecuteCommandResponse, InstallRequest, JoinNetworkRequest,
    LeaveNetworkRequest, ListRequest, PeersRequest, PingRequest, PullRequest, PushRequest,
    RegisterRequest, RestartServiceRequest, ServerRequest, UninstallRequest, UseRequest,
    VersionRequest,
};

/// Configuration for a remote gRPC endpoint
#[derive(Debug, Clone)]
pub struct RemoteEndpoint {
    pub address: String,
    pub tls_enabled: bool,
    pub connect_timeout: Duration,
    pub request_timeout: Duration,
}

/// Caller-supplied Ghostbridge identity forwarded by an HTTP compatibility
/// adapter into the canonical gRPC method call.
#[derive(Debug, Clone)]
pub struct GhostbridgeCallMetadata {
    pub footprint: String,
    pub trace_id: Option<String>,
    pub wireguard_pubkey: Option<String>,
}

impl Default for RemoteEndpoint {
    fn default() -> Self {
        Self {
            address: "http://127.0.0.1:8090".to_string(),
            tls_enabled: false,
            connect_timeout: Duration::from_secs(5),
            request_timeout: Duration::from_secs(30),
        }
    }
}

/// gRPC client pool for connecting to remote Operation services
pub struct GrpcClientPool {
    /// Map of endpoint address to channel
    channels: RwLock<HashMap<String, Channel>>,
    /// Default endpoint configuration
    default_config: RemoteEndpoint,
}

impl Default for GrpcClientPool {
    fn default() -> Self {
        Self::new()
    }
}

impl GrpcClientPool {
    pub fn new() -> Self {
        Self {
            channels: RwLock::new(HashMap::new()),
            default_config: RemoteEndpoint::default(),
        }
    }

    pub fn with_default_config(config: RemoteEndpoint) -> Self {
        Self {
            channels: RwLock::new(HashMap::new()),
            default_config: config,
        }
    }

    /// Get or create a channel to the specified address (supports comma-separated endpoints for load balancing)
    async fn get_channel(&self, address: &str) -> Result<Channel, GrpcClientError> {
        {
            let channels = self.channels.read().await;
            if let Some(channel) = channels.get(address) {
                return Ok(channel.clone());
            }
        }

        let addrs: Vec<&str> = address
            .split(',')
            .map(|s| s.trim())
            .filter(|s| !s.is_empty())
            .collect();

        let channel = if addrs.len() > 1 {
            // Native Tonic Load Balancing
            let endpoints = addrs
                .into_iter()
                .map(|addr| {
                    Endpoint::from_shared(addr.to_string()).map(|e| {
                        e.connect_timeout(self.default_config.connect_timeout)
                            .timeout(self.default_config.request_timeout)
                    })
                })
                .collect::<Result<Vec<_>, _>>()
                .map_err(|e| {
                    GrpcClientError::ConnectionFailed(format!("Invalid endpoint: {}", e))
                })?;

            Channel::balance_list(endpoints.into_iter())
        } else {
            // Single endpoint
            let endpoint = Endpoint::from_shared(address.to_string())
                .map_err(|e| GrpcClientError::ConnectionFailed(e.to_string()))?
                .connect_timeout(self.default_config.connect_timeout)
                .timeout(self.default_config.request_timeout);

            endpoint
                .connect()
                .await
                .map_err(|e| GrpcClientError::ConnectionFailed(e.to_string()))?
        };

        {
            let mut channels = self.channels.write().await;
            channels.insert(address.to_string(), channel.clone());
        }

        info!("Connected to remote gRPC endpoint(s): {}", address);
        Ok(channel)
    }

    /// Get a Plugin service client
    pub async fn plugin_service_client(
        &self,
        address: &str,
    ) -> Result<PluginServiceClient<Channel>, GrpcClientError> {
        let channel = self.get_channel(address).await?;
        Ok(PluginServiceClient::new(channel))
    }

    /// Get a StateSync service client
    pub async fn state_sync_client(
        &self,
        address: &str,
    ) -> Result<StateSyncClient<Channel>, GrpcClientError> {
        let channel = self.get_channel(address).await?;
        Ok(StateSyncClient::new(channel))
    }

    /// Get an EventChain service client
    pub async fn event_chain_client(
        &self,
        address: &str,
    ) -> Result<EventChainServiceClient<Channel>, GrpcClientError> {
        let channel = self.get_channel(address).await?;
        Ok(EventChainServiceClient::new(channel))
    }

    /// Get a Netmaker adapter client.
    pub async fn netmaker_client(
        &self,
        address: &str,
    ) -> Result<NetmakerServiceClient<Channel>, GrpcClientError> {
        let channel = self.get_channel(address).await?;
        Ok(NetmakerServiceClient::new(channel))
    }

    /// Close all connections
    pub async fn close_all(&self) {
        let mut channels = self.channels.write().await;
        channels.clear();
        info!("Closed all gRPC client connections");
    }
}

/// High-level client for remote Operation services
#[allow(dead_code)]
pub struct RemoteOperationClient {
    pool: Arc<GrpcClientPool>,
    default_address: String,
    client_id: String,
}

impl RemoteOperationClient {
    pub fn new(pool: Arc<GrpcClientPool>, address: &str, client_id: &str) -> Self {
        Self {
            pool,
            default_address: address.to_string(),
            client_id: client_id.to_string(),
        }
    }

    /// Get state from a remote endpoint
    pub async fn get_state(
        &self,
        plugin_id: &str,
        object_path: &str,
    ) -> Result<simd_json::OwnedValue, GrpcClientError> {
        let mut client = self.pool.state_sync_client(&self.default_address).await?;

        let mut request = Request::new(GetStateRequest {
            plugin_id: plugin_id.to_string(),
            object_path: object_path.to_string(),
        });
        attach_ghostbridge_metadata(&mut request)?;

        let response = client
            .get_state(request)
            .await
            .map_err(|e| GrpcClientError::RequestFailed(e.to_string()))?;

        let resp = response.into_inner();
        let state = resp.state.unwrap_or_default();
        Ok(prost_struct_to_simd(&state))
    }

    /// Set state on a remote endpoint (apply patch)
    pub async fn set_state(
        &self,
        plugin_id: &str,
        object_path: &str,
        state: simd_json::OwnedValue,
        actor_id: &str,
        capability_id: &str,
    ) -> Result<SetStateResult, GrpcClientError> {
        let mut client = self.pool.state_sync_client(&self.default_address).await?;

        let mut request = Request::new(MutateRequest {
            plugin_id: plugin_id.to_string(),
            object_path: object_path.to_string(),
            operation: ProtoOperationType::ApplyPatch as i32,
            member_name: String::new(),
            value: Some(simd_to_prost_value(&state)),
            actor_id: actor_id.to_string(),
            capability_id: capability_id.to_string(),
            idempotency_key: uuid::Uuid::new_v4().to_string(),
        });
        attach_ghostbridge_metadata(&mut request)?;

        let response = client
            .mutate(request)
            .await
            .map_err(|e| GrpcClientError::RequestFailed(e.to_string()))?;

        let resp = response.into_inner();
        if !resp.success {
            if let Some(err) = resp.error {
                return Err(GrpcClientError::RemoteError {
                    code: format!("{}", err.code),
                    message: err.message,
                });
            }
            return Err(GrpcClientError::RemoteError {
                code: "UNKNOWN".to_string(),
                message: "mutation failed".to_string(),
            });
        }

        Ok(SetStateResult {
            event_id: resp.event_id,
            effective_hash: resp.effective_hash,
        })
    }

    /// Call a method on a remote endpoint
    #[allow(clippy::too_many_arguments)]
    pub async fn call_method(
        &self,
        plugin_id: &str,
        object_path: &str,
        interface_name: &str,
        method_name: &str,
        arguments: Vec<simd_json::OwnedValue>,
        actor_id: &str,
        capability_id: &str,
    ) -> Result<simd_json::OwnedValue, GrpcClientError> {
        let mut client = self
            .pool
            .plugin_service_client(&self.default_address)
            .await?;

        let arguments = arguments
            .iter()
            .map(simd_to_prost_value)
            .collect::<Vec<_>>();

        let mut request = Request::new(CallMethodRequest {
            plugin_id: plugin_id.to_string(),
            object_path: object_path.to_string(),
            interface_name: interface_name.to_string(),
            method_name: method_name.to_string(),
            arguments,
            actor_id: actor_id.to_string(),
            capability_id: capability_id.to_string(),
        });
        attach_ghostbridge_metadata(&mut request)?;

        let response = client
            .call_method(request)
            .await
            .map_err(|e| GrpcClientError::RequestFailed(e.to_string()))?;

        let resp = response.into_inner();
        if !resp.success {
            if let Some(err) = resp.error {
                return Err(GrpcClientError::RemoteError {
                    code: format!("{}", err.code),
                    message: err.message,
                });
            }
            return Err(GrpcClientError::RemoteError {
                code: "UNKNOWN".to_string(),
                message: "call failed".to_string(),
            });
        }

        if let Some(result) = resp.result {
            Ok(prost_value_to_simd(&result))
        } else {
            Ok(simd_json::json!(null))
        }
    }

    /// Call a method while preserving the Ghostbridge identity supplied by an
    /// outer transport adapter. This keeps HTTP on op-web while capability
    /// enforcement remains in the bridge's canonical gRPC method pipeline.
    #[allow(clippy::too_many_arguments)]
    pub async fn call_method_with_metadata(
        &self,
        plugin_id: &str,
        object_path: &str,
        interface_name: &str,
        method_name: &str,
        arguments: Vec<simd_json::OwnedValue>,
        actor_id: &str,
        capability_id: &str,
        identity: &GhostbridgeCallMetadata,
    ) -> Result<simd_json::OwnedValue, GrpcClientError> {
        let mut client = self
            .pool
            .plugin_service_client(&self.default_address)
            .await?;

        let arguments = arguments
            .iter()
            .map(simd_to_prost_value)
            .collect::<Vec<_>>();

        let mut request = Request::new(CallMethodRequest {
            plugin_id: plugin_id.to_string(),
            object_path: object_path.to_string(),
            interface_name: interface_name.to_string(),
            method_name: method_name.to_string(),
            arguments,
            actor_id: actor_id.to_string(),
            capability_id: capability_id.to_string(),
        });
        attach_supplied_ghostbridge_metadata(&mut request, identity)?;

        let response = client
            .call_method(request)
            .await
            .map_err(|e| GrpcClientError::RequestFailed(e.to_string()))?;

        let resp = response.into_inner();
        if !resp.success {
            if let Some(err) = resp.error {
                return Err(GrpcClientError::RemoteError {
                    code: format!("{}", err.code),
                    message: err.message,
                });
            }
            return Err(GrpcClientError::RemoteError {
                code: "UNKNOWN".to_string(),
                message: "call failed".to_string(),
            });
        }

        if let Some(result) = resp.result {
            Ok(prost_value_to_simd(&result))
        } else {
            Ok(simd_json::json!(null))
        }
    }

    /// Subscribe to state updates from a remote endpoint
    pub async fn subscribe(
        &self,
        plugin_filters: Vec<String>,
        path_filters: Vec<String>,
        tag_filters: Vec<String>,
    ) -> Result<
        impl tokio_stream::Stream<Item = Result<StateUpdateMessage, GrpcClientError>>,
        GrpcClientError,
    > {
        let mut client = self.pool.state_sync_client(&self.default_address).await?;

        let mut request = Request::new(SubscribeRequest {
            plugin_ids: plugin_filters,
            path_patterns: path_filters,
            tags: tag_filters,
            include_initial_state: false,
        });
        attach_ghostbridge_metadata(&mut request)?;

        let response = client
            .subscribe(request)
            .await
            .map_err(|e| GrpcClientError::RequestFailed(e.to_string()))?;

        let stream = response.into_inner();

        Ok(tokio_stream::StreamExt::map(stream, |result| {
            result
                .map(|update| StateUpdateMessage {
                    plugin_id: update.plugin_id,
                    object_path: update.object_path,
                    property_name: if update.member_name.is_empty() {
                        None
                    } else {
                        Some(update.member_name)
                    },
                    new_value: update.new_value.as_ref().map(prost_value_to_simd),
                    event_id: update.event_id.to_string(),
                    tags_touched: update.tags_touched,
                })
                .map_err(|e| GrpcClientError::StreamError(e.to_string()))
        }))
    }

    /// Subscribe to chain events from a remote endpoint
    pub async fn stream_events(
        &self,
        from_event_id: Option<u64>,
        plugin_filters: Vec<String>,
        tag_filters: Vec<String>,
    ) -> Result<
        impl tokio_stream::Stream<Item = Result<ChainEventMessage, GrpcClientError>>,
        GrpcClientError,
    > {
        let mut client = self.pool.event_chain_client(&self.default_address).await?;

        let mut request = Request::new(SubscribeEventsRequest {
            from_event_id: from_event_id.unwrap_or_default(),
            plugin_id: plugin_filters.first().cloned().unwrap_or_default(),
            tags: tag_filters,
        });
        attach_ghostbridge_metadata(&mut request)?;

        let response = client
            .subscribe_events(request)
            .await
            .map_err(|e| GrpcClientError::RequestFailed(e.to_string()))?;

        let stream = response.into_inner();

        Ok(tokio_stream::StreamExt::map(stream, |result| {
            result
                .map(|event| ChainEventMessage {
                    event_id: event.event_id.to_string(),
                    event_hash: event.event_hash,
                    prev_hash: event.prev_hash,
                    plugin_id: event.plugin_id,
                    operation_type: event.operation_type,
                    target: event.target,
                    decision: event.decision.to_string(),
                    tags_touched: event.tags_touched,
                })
                .map_err(|e| GrpcClientError::StreamError(e.to_string()))
        }))
    }
}

/// Result of a set state operation
#[derive(Debug, Clone)]
pub struct SetStateResult {
    pub event_id: u64,
    pub effective_hash: String,
}

/// State update message from subscription
#[derive(Debug, Clone)]
