        let current_hash = self.compute_state_hash(&current_state);
        let desired_hash = self.compute_state_hash(&simd_json::serde::to_owned_value(desired)?);

        Ok(StateDiff {
            plugin: "openflow".to_string(),
            actions,
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash,
                desired_hash,
            },
        })
    }

    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
        log::info!(
            "Applying OpenFlow state changes: {} actions",
            diff.actions.len()
        );

        let mut changes = Vec::new();
        let mut errors = Vec::new();
        let mut create_ports = Vec::new();
        let mut create_flows = Vec::new();
        let mut delete_flows = Vec::new();
        let mut delete_ports = Vec::new();
        let mut modify_actions = Vec::new();

        for action in &diff.actions {
            match action {
                StateAction::Create { resource, .. } if resource.contains("/port/") => {
                    create_ports.push(action);
                }
                StateAction::Create { resource, .. } if resource.contains("/flow/") => {
                    create_flows.push(action);
                }
                StateAction::Delete { resource } if resource.contains("/flow/") => {
                    delete_flows.push(action);
                }
                StateAction::Delete { resource } if resource.contains("/port/") => {
                    delete_ports.push(action);
                }
                StateAction::Modify { .. } => modify_actions.push(action),
                StateAction::NoOp { .. } => {}
                _ => {}
            }
        }

        for action in create_ports {
            if let StateAction::Create { resource, config } = action {
                let parts: Vec<&str> = resource.split('/').collect();
                let bridge = parts[0];
                let port: SocketPort = simd_json::serde::from_owned_value(config.clone())?;
                match self.create_socket_port(bridge, &port).await {
                    Ok(_) => changes.push(format!("Created socket port {}", port.name)),
                    Err(e) => errors.push(format!("Failed to create port {}: {}", port.name, e)),
                }
            }
        }

        for action in create_flows {
            if let StateAction::Create { resource, config } = action {
                let parts: Vec<&str> = resource.split('/').collect();
                let bridge = parts[0];
                let flow: FlowEntry = simd_json::serde::from_owned_value(config.clone())?;
                match self.install_flow(bridge, &flow).await {
                    Ok(_) => {
                        changes.push(format!("Installed flow {}", Self::flow_resource_id(&flow)))
                    }
                    Err(e) => errors.push(format!(
                        "Failed to install flow {} on {}: {}",
                        Self::flow_resource_id(&flow),
                        bridge,
                        e
                    )),
                }
            }
        }

        for action in delete_flows {
            if let StateAction::Delete { resource } = action {
                let parts: Vec<&str> = resource.split('/').collect();
                let bridge = parts[0];
                let flow_id = parts.get(2).copied().unwrap_or_default();
                match self.query_flows(bridge).await {
                    Ok(flows) => {
                        if let Some(flow) = flows
                            .into_iter()
                            .find(|flow| Self::flow_resource_id(flow) == flow_id)
                        {
                            match self.delete_flow(bridge, &flow).await {
                                Ok(_) => changes.push(format!("Deleted flow {}", flow_id)),
                                Err(e) => errors.push(format!(
                                    "Failed to delete flow {} on {}: {}",
                                    flow_id, bridge, e
                                )),
                            }
                        }
                    }
                    Err(e) => errors.push(format!(
                        "Failed to query current flows for {} before deleting {}: {}",
                        bridge, flow_id, e
                    )),
                }
            }
        }

        for action in delete_ports {
            if let StateAction::Delete { resource } = action {
                let parts: Vec<&str> = resource.split('/').collect();
                let bridge = parts[0];
                let port_name = parts[2];
                match self.delete_socket_port(bridge, port_name).await {
                    Ok(_) => changes.push(format!("Deleted socket port {}", port_name)),
                    Err(e) => errors.push(format!("Failed to delete port {}: {}", port_name, e)),
                }
            }
        }

        for action in modify_actions {
            if let StateAction::Modify {
                resource,
                changes: config,
            } = action
            {
                let parts: Vec<&str> = resource.split('/').collect();
                let bridge = parts[0];
                let flow: FlowEntry = simd_json::serde::from_owned_value(config.clone())?;
                let flow_id = Self::flow_resource_id(&flow);
                match self.query_flows(bridge).await {
                    Ok(flows) => {
                        if let Some(existing) = flows
                            .into_iter()
                            .find(|current| Self::flow_resource_id(current) == flow_id)
                        {
                            if let Err(e) = self.delete_flow(bridge, &existing).await {
                                errors.push(format!(
                                    "Failed to replace flow {} on {}: {}",
                                    flow_id, bridge, e
                                ));
                                continue;
                            }
                        }
                        match self.install_flow(bridge, &flow).await {
                            Ok(_) => changes.push(format!("Updated flow {}", flow_id)),
                            Err(e) => errors.push(format!(
                                "Failed to update flow {} on {}: {}",
                                flow_id, bridge, e
                            )),
                        }
                    }
                    Err(e) => errors.push(format!(
                        "Failed to query current flows for {} before updating {}: {}",
                        bridge, flow_id, e
                    )),
                }
            }
        }

        Ok(ApplyResult {
            success: errors.is_empty(),
            changes_applied: changes,
            errors,
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        let current_state = simd_json::json!(null);

        Ok(Checkpoint {
            id: format!("openflow_{}", chrono::Utc::now().timestamp()),
            plugin: "openflow".to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: current_state,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, checkpoint: &Checkpoint) -> Result<()> {
        log::info!(
            "Rolling back OpenFlow to checkpoint from {}",
            checkpoint.timestamp
        );

        let current = simd_json::json!(null);
        let diff = self
            .calculate_diff(&current, &checkpoint.state_snapshot)
            .await?;

        self.apply_state(&diff).await?;

        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: true,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false, // Flows installed one by one
        }
    }
}

pub(crate) fn openflow_schema() -> PluginSchema {
    let root = serde_json::to_value(schemars::schema_for!(OpenFlowConfig))
        .expect("schemars schema serializes to JSON");
    let mut schema = super::schemars_adapter::plugin_schema_from_json(
        "openflow",
        "1.0.0",
        "OpenFlow flow table management",
        &root,
    );
    schema.dependencies = vec!["net".to_string()];
    schema.example = Some(json!({
        "bridges": [
            {
                "name": "ovsbr0",
                "socket_ports": [
                    {
                        "name": "ovsbr0-sock",
                        "port_type": "SharedIngress"
                    }
                ],
                "flows": [
                    {
                        "table": 0,
                        "priority": 22000,
                        "match_fields": {"in_port": "ovsbr0-sock", "ip": "", "nw_src": "10.100.0.2"},
                        "actions": [{"type": "output", "port": "gbr_wg"}],
                        "cookie": 5787125521171081216u64,
                        "idle_timeout": 0,
                        "hard_timeout": 0
                    }
                ]
            }
        ],
        "auto_discover_containers": false,
        "enable_security_flows": false,
        "obfuscation_level": 0
    }));

    // Add D-Bus methods for OpenFlow - https://www.opennetworking.org/wp-content/uploads/2014/10/of_spec_1_0.pdf
    schema.methods.insert(
        "add_flow".to_string(),
        super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<
            AddFlowInput,
            super::plugin_scaffold_helpers::AckOutput,
        >(
            "AddFlow",
            op_state_store::SideEffect::Mutation,
            false,
            "openflow.write",
            "mut.network.openflow.flow.add@v1",
        ),
    );
    schema.methods.insert(
        "delete_flow".to_string(),
        super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<
            DeleteFlowInput,
            super::plugin_scaffold_helpers::AckOutput,
        >(
            "DeleteFlow",
            op_state_store::SideEffect::Mutation,
            false,
            "openflow.write",
            "mut.network.openflow.flow.delete@v1",
        ),
    );
    schema.methods.insert(
        "modify_flow".to_string(),
        super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<
            ModifyFlowInput,
            super::plugin_scaffold_helpers::AckOutput,
        >(
            "ModifyFlow",
            op_state_store::SideEffect::Mutation,
            false,
            "openflow.write",
            "mut.network.openflow.flow.modify@v1",
        ),
    );

    schema
}

/// Input struct for AddFlow method
/// D-Bus method spec: https://www.opennetworking.org/wp-content/uploads/2014/10/of_spec_1_0.pdf
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct AddFlowInput {
    /// Bridge name

    for tok in s.split('+').filter(|t| !t.is_empty()) {
        bits |= match tok {
            "new" => 0x01,
            "est" => 0x02,
            "rel" => 0x04,
            "rpl" => 0x08,
            "inv" => 0x10,
            "trk" => 0x20,
            "snat" => 0x40,
            "dnat" => 0x80,
            other => bail!("unknown ct_state token '+{}' in '{}'", other, s),
        };
    }
    Ok((bits, bits))
}

/// Translate `match_fields` into a `rovs_openflow::Match`.
///
/// Two passes: first detect protocol markers (`tcp`/`udp`/`icmp`/`icmp6`/
/// `arp`/`ip`) to establish `eth_type`/`ip_proto` context, since `HashMap`
/// iteration order can't be relied on to see e.g. `udp` before `tp_dst`.
fn parse_match(fields: &HashMap<String, String>, port_map: &HashMap<String, u32>) -> Result<Match> {
    let mut m = Match::new();
    let mut ip_proto: Option<u8> = None;
    let mut eth_type: Option<u16> = None;

    if fields.contains_key("arp") {
        eth_type = Some(0x0806);
    }
    if fields.contains_key("icmp6") {
        eth_type = Some(0x86dd);
        ip_proto = Some(58);
    }
    if fields.contains_key("ip") {
        eth_type = eth_type.or(Some(0x0800));
    }
    if fields.contains_key("tcp") {
        eth_type = eth_type.or(Some(0x0800));
        ip_proto = ip_proto.or(Some(6));
    }
    if fields.contains_key("udp") {
        eth_type = eth_type.or(Some(0x0800));
        ip_proto = ip_proto.or(Some(17));
    }
    if fields.contains_key("icmp") {
        eth_type = eth_type.or(Some(0x0800));
        ip_proto = ip_proto.or(Some(1));
    }
    if let Some(et) = eth_type {
        m = m.eth_type(et);
    }
    if let Some(p) = ip_proto {
        m = m.ip_proto(p);
    }

    for (k, v) in fields {
        m = match k.as_str() {
            "arp" | "ip" | "tcp" | "udp" | "icmp" | "icmp6" => m, // handled above
            "in_port" => m.in_port(resolve_port(v, port_map)?),
            "dl_type" => {
                let et = if let Some(hex) = v.strip_prefix("0x") {
                    u16::from_str_radix(hex, 16)
                        .with_context(|| format!("invalid dl_type '{v}'"))?
                } else {
                    v.parse()
                        .with_context(|| format!("invalid dl_type '{v}'"))?
                };
                m.eth_type(et)
            }
            "dl_vlan" => m.vlan_vid(
                v.parse()
                    .with_context(|| format!("invalid dl_vlan '{v}'"))?,
            ),
            "dl_src" => m.eth_src(parse_mac(v)?),
            "tcp_flags" => {
                let mut m2 = m;
                m2.tcp_flags = Some(parse_tcp_flags(v)?);
                m2
            }
            "tp_src" => {
                let port: u16 = v.parse().with_context(|| format!("invalid tp_src '{v}'"))?;
                match ip_proto {
                    Some(6) => m.tcp_src(port),
                    Some(17) => m.udp_src(port),
                    _ => bail!("tp_src requires a 'tcp' or 'udp' marker in match_fields"),
                }
            }
            "tp_dst" => {
                let port: u16 = v.parse().with_context(|| format!("invalid tp_dst '{v}'"))?;
                match ip_proto {
                    Some(6) => m.tcp_dst(port),
                    Some(17) => m.udp_dst(port),
                    _ => bail!("tp_dst requires a 'tcp' or 'udp' marker in match_fields"),
                }
            }
            "nw_src" => {
                let (addr, prefix) = parse_cidr(v)?;
                m.ipv4_src(addr, prefix)
            }
            "nw_dst" => {
                let (addr, prefix) = parse_cidr(v)?;
                m.ipv4_dst(addr, prefix)
            }
            "ct_state" => {
                let (state, mask) = parse_ct_state(v)?;
                m.ct_state_masked(state, mask)
            }
            other => bail!(
                "unsupported OpenFlow match field '{}'={:?} — no translation available \
                 (rovs-openflow's Match type has no equivalent field)",
                other,
                v
            ),
        };
    }
    Ok(m)
}

/// Translate `actions` into a `rovs_openflow::ActionList`.
///
/// `ip_proto` (established while parsing match_fields) disambiguates
/// protocol-relative `SetField` targets like `tp_dst`.
fn build_actions(
    actions: &[JsonFlowAction],
    port_map: &HashMap<String, u32>,
    ip_proto: Option<u8>,
) -> Result<ActionList> {
    let mut list = ActionList::new();
    for a in actions {
        list = match a {
            JsonFlowAction::Output { port } => {
                if port.eq_ignore_ascii_case("LOCAL") {
                    list.output(OutputPort::Local)
                } else if port.eq_ignore_ascii_case("NORMAL") {
                    list.output(OutputPort::Normal)
                } else if port.eq_ignore_ascii_case("FLOOD") {
                    list.output(OutputPort::Flood)
                } else if port.eq_ignore_ascii_case("ALL") {
                    list.output(OutputPort::All)
                } else if port.eq_ignore_ascii_case("IN_PORT") {
                    list.output(OutputPort::InPort)
                } else if port.eq_ignore_ascii_case("CONTROLLER") {
                    list.output(OutputPort::Controller)
                } else {
                    list.output(OutputPort::Port(resolve_port(port, port_map)?))
                }
            }
            JsonFlowAction::Drop => list.drop(),
            JsonFlowAction::Normal => list.normal(),
            JsonFlowAction::Controller { max_len } => list.controller(max_len.unwrap_or(128)),
            JsonFlowAction::Resubmit { table } => list.resubmit_table(*table),
            JsonFlowAction::LoadRegister { register, value } => {
                let field = match register {
                    0 => nxm::REG0,
                    1 => nxm::REG1,
                    2 => nxm::REG2,
                    other => bail!(
                        "unsupported register {} — rovs-openflow only exposes NXM_NX_REG0..REG2",
                        other
                    ),
                };
                list.load_field(field, 0, 32, *value)
            }
            JsonFlowAction::SetField { field, value } => match field.as_str() {
                "dl_dst" | "eth_dst" => list.set_eth_dst(parse_mac(value)?),
                "dl_src" | "eth_src" => list.set_eth_src(parse_mac(value)?),
                "dl_vlan" | "vlan_vid" => {
                    let vid: u16 = value
                        .parse()
                        .with_context(|| format!("invalid vlan_vid '{value}'"))?;
                    list.set_vlan_vid(vid)
                }
                "tun_id" | "tunnel_id" => {
                    let id: u64 = value
                        .parse()
                        .with_context(|| format!("invalid tunnel_id '{value}'"))?;
                    list.set_tunnel_id(id)
                }
                "tp_dst" => {
                    let port: u16 = value
                        .parse()
                        .with_context(|| format!("invalid tp_dst '{value}'"))?;
                    match ip_proto {
                        Some(6) => list.load_field(nxm::TCP_DST, 0, 16, port as u64),
                        Some(17) => list.load_field(nxm::UDP_DST, 0, 16, port as u64),
                        _ => bail!(
                            "SetField tp_dst requires a 'tcp' or 'udp' marker in match_fields"
                        ),
                    }
                }
                "tp_src" => {
                    let port: u16 = value
                        .parse()
                        .with_context(|| format!("invalid tp_src '{value}'"))?;
                    match ip_proto {
                        Some(6) => list.load_field(nxm::TCP_SRC, 0, 16, port as u64),
                        Some(17) => list.load_field(nxm::UDP_SRC, 0, 16, port as u64),
                        _ => bail!(
                            "SetField tp_src requires a 'tcp' or 'udp' marker in match_fields"
                        ),
                    }
                }
                other => bail!(
                    "unsupported SetField target '{}'={:?} — no NXM field available in rovs-openflow",
                    other,
                    value
                ),
            },
            JsonFlowAction::ArpResponder { mac, ip } => {
                let mac_bytes = parse_mac(mac)?;
                let ip_addr = parse_ipv4(ip)?;
                list
                    // dst mac := original src mac; src mac := our mac
                    .move_field(nxm::ETH_SRC, nxm::ETH_DST, 48, 0, 0)
                    .set_eth_src(mac_bytes)
                    // ARP reply
                    .set_arp_op(2)
                    // tha := original sha; sha := our mac
                    .move_field(nxm::ARP_SHA, nxm::ARP_THA, 48, 0, 0)
                    .set_arp_sha(mac_to_u64(mac_bytes))

                        );
                    }
                }
            });
        }
    }
}

/// A cloneable handle for pushing schema-driven flows to whichever switch is
/// currently connected to an `OpenFlowController`, obtained via
/// `OpenFlowController::handle()` before calling `run()`.
///
/// This is what backs the `org.opdbus.v1.plugins.openflow` D-Bus interface
/// exposed by the `op-of-controller` binary — the openflow plugin's
/// `install_flow`/`delete_flow`/`query_flows` call through it instead of the
/// old (broken, now-removed) `op-openvswitch-daemon` passthrough.
#[derive(Clone)]
pub struct OpenFlowControllerHandle {
    active_conn: Arc<Mutex<Option<mpsc::UnboundedSender<FlowRequest>>>>,
    installed_flows: Arc<Mutex<Vec<serde_json::Value>>>,
}

impl OpenFlowControllerHandle {
    /// Install or delete one schema-driven `FlowEntry` (JSON, matching the
    /// openflow plugin's shape) on the currently connected switch.
    pub async fn send_flow(&self, flow_json: String, delete: bool) -> Result<String> {
        let value: serde_json::Value =
            serde_json::from_str(&flow_json).context("invalid flow JSON")?;

        let (tx, rx) = oneshot::channel();
        {
            let guard = self.active_conn.lock().unwrap();
            let sender = guard
                .as_ref()
                .context("no OVS switch currently connected to the OpenFlow controller")?;
            sender
                .send(FlowRequest {
                    flow_json,
                    delete,
                    reply: tx,
                })
                .map_err(|_| anyhow::anyhow!("controller connection task is no longer running"))?;
        }
        let result: Result<String> = rx.await.context("controller dropped the reply channel")?;
        let result = result?;

        let mut flows = self.installed_flows.lock().unwrap();
        flows.retain(|f| f != &value);
        if !delete {
            flows.push(value);
        }
        Ok(result)
    }

    /// Return the flows this handle believes are currently installed
    /// (tracked in-memory since they were pushed through `send_flow` —
    /// this is not a live re-query of the switch's flow table).
    pub fn dump_flows(&self) -> Vec<String> {
        self.installed_flows
            .lock()
            .unwrap()
            .iter()
            .map(|v| v.to_string())
            .collect()
    }
}

