content.data:
    &self,
    plugin_id: &str,
    method: &str,
    json_args: &str,
    capability_id: Option<&str>,
    actor_id: &str,
) -> anyhow::Result<serde_json::Value> {
    // Test-only: ForceDispatchError triggers an error for VAL-DISPATCH-003 testing.
    // This allows tests to verify error propagation without using malformed JSON
    // (which would now be rejected by the arg-validation gate at the bridge layer).
    if method == "ForceDispatchError" {
        return Err(anyhow::anyhow!(
            "dispatch error: method explicitly triggered failure"
        ));
    }

    // Parse the verbatim json_args string. If parsing fails, propagate
    // the error — the bridge converts it to fdo::Error::Failed.
    let parsed_value: simd_json::OwnedValue = {
        let mut bytes = json_args.as_bytes().to_vec();
        simd_json::to_owned_value(&mut bytes)
            .map_err(|e| anyhow::anyhow!("invalid json_args for method '{}': {}", method, e))?
    };

    // Record the immutable event with the full accountability surface.
    // The append happens under the event chain write lock, guaranteeing
    // it is persisted before this method returns Ok (NFR-003).
    let event_summary = {
        let mut chain = self.event_chain.write().await;
        let event = chain.record_method_call(
            actor_id.to_string(),
            plugin_id.to_string(),
            method.to_string(),
            capability_id.map(|s| s.to_string()),
            json_args, // verbatim string for Blake3 footprint
        );
        (
            event.event_id,
            event.event_hash.clone(),
            event.timestamp,
            event.clone(),
        )
    };

    // Durability: write the event to the timing_subvol before returning, so
    // the audit trail survives a restart (FR-6). A failure here is logged
    // and does not fail the dispatch (NFR-4).
    self.persist_audit_event(&event_summary.3).await;

    // Broadcast the method-call change to gRPC subscribers.
    let change = StateChange {
        change_id: uuid::Uuid::new_v4().to_string(),
        event_id: event_summary.0,
        plugin_id: plugin_id.to_string(),
        object_path: format!("/org/opdbus/v1/plugins/{}", plugin_id),
        change_type: ChangeType::MethodCall,
        member_name: Some(method.to_string()),
        old_value: None,
        new_value: parsed_value.clone(),
        tags_touched: vec![],
        event_hash: event_summary.1.clone(),
        timestamp: event_summary.2,
        actor_id: actor_id.to_string(),
        source: ChangeSource::DBus,
    };
    let _ = self.change_tx.send(change.clone());

    // Dispatch to appropriate backend based on plugin_id
    let method_result: serde_json::Value = match plugin_id {
        "rovs_commands" => {
            dispatch_rovs_commands_method(&self.ovsdb, method, &parsed_value).await?
        }
        "ovsdb_bridge" => {
            dispatch_ovsdb_bridge_method(&self.ovsdb, method, &parsed_value).await?
        }
        "xray" => {
            let args = serde_json::to_value(&parsed_value)?;
            dispatch_xray_method(method, &args).await?
        }
        "identity_sled" => {
            let args = serde_json::to_value(&parsed_value)?;
            crate::identity_sled_dispatch::dispatch_identity_sled_method(self, method, &args)
                .await?
        }
        "persona" => {
            let args = serde_json::to_value(&parsed_value)?;
            op_plugins::state_plugins::persona::dispatch_persona_method(method, &args).await?
        }
        "gcloud_adc" => {
            let args = serde_json::to_value(&parsed_value)?;
            op_plugins::state_plugins::gcloud_adc::dispatch_gcloud_adc_method(method, &args)
                .await?
        }
        "compact_mcp" => {
            let args = serde_json::to_value(&parsed_value)?;
            op_plugins::state_plugins::compact_mcp::dispatch_compact_mcp_method(method, &args)
                .await?
        }
        "full_system" => {
            let args = serde_json::to_value(&parsed_value)?;
            op_plugins::state_plugins::full_system::dispatch_full_system_method(
                method, &args,
            )
            .await?
        }
        "keyring" => {
            let args = serde_json::to_value(&parsed_value)?;
            op_plugins::state_plugins::keyring::dispatch_keyring_method(method, &args).await?
        }
        "privacy_routes" => {
            let args = serde_json::to_value(&parsed_value)?;
            op_plugins::state_plugins::privacy_routes::dispatch_privacy_routes_method(
                method, &args,
            )
            .await?
        }
        "zeroclaw" => {
            let state = self
                .projected_state::<op_plugins::state_plugins::zeroclaw::ZeroclawState>(
                    "zeroclaw",
                )
                .await
                .unwrap_or_else(
                    op_plugins::state_plugins::zeroclaw::ZeroclawPlugin::current_state,
                );
            if method == "Chat" {
                let args = serde_json::from_value::<
                    op_plugins::state_plugins::zeroclaw::ChatInput,
                >(serde_json::to_value(&parsed_value)?)
                .context("invalid zeroclaw.Chat arguments")?;
                serde_json::to_value(
                    crate::chat_service::dispatch_schema_chat(
                        self.chat_manager.as_ref(),
                        &state,
                        args,
                    )
                    .await?,
                )?
            } else {
                match op_plugins::state_plugins::zeroclaw::dispatch_zeroclaw_method(
                    method, json_args, &state,
                ) {
                    Ok(outcome) => {
                        if method.starts_with("Set") {
                            self.persist_zeroclaw_mutation(method, &outcome.result)
                                .await?;
                        }
                        if let Some(sig) = &outcome.signal {
                            self.broadcast_method_signal(&change, &sig.name, &sig.payload);
                        }
                        outcome.result
                    }
                    Err(e) => {
                        return Err(anyhow::anyhow!(
                            "zeroclaw dispatch error for '{}': {}",
                            method,
                            e
                        ))
                    }
                }
            }
        }
        "ghostbridge" => {
            let state = self
                .projected_state::<op_plugins::state_plugins::ghostbridge::GhostbridgeState>(
                    "ghostbridge",
                )
                .await
                .unwrap_or_else(
                    op_plugins::state_plugins::ghostbridge::GhostbridgePlugin::current_state,
                );
            op_plugins::state_plugins::ghostbridge::dispatch_ghostbridge_method(method, &state)?
        }
        "cognitive_mcp" => {
            let args = serde_json::to_value(&parsed_value)?;
            dispatch_cognitive_mcp_method(method, &args).await?
        }
        // Audit-trail query surface. Deliberately scoped: only the two
        // audit methods are wired. The plugin's seven pre-existing methods
        // (snapshots, retention, rollback) fall through to the echo below,
        // exactly as before, until the schema-methods sweep wires them.
        "snowball" => match method {
            "query_events" => {
                dispatch_snowball_query_events(&self.event_chain, &parsed_value).await?
            }
            "verify_chain" => {
                dispatch_snowball_verify_chain(&self.event_chain, &parsed_value).await?
            }
            _ => serde_json::to_value(&parsed_value).unwrap_or(serde_json::Value::Null),
        },
        _ => serde_json::to_value(&parsed_value).unwrap_or(serde_json::Value::Null),
    };

    // Return a JSON result carrying the event accountability proof and the
    // method's domain result. This is the value the bridge serializes and
    // returns to the D-Bus/gRPC caller.
    let result = serde_json::json!({
        "success": true,
        "event_id": change.event_id,
        "event_hash": change.event_hash,
        "plugin_id": plugin_id,
        "method": method,
        "result": method_result,
    });
    Ok(result)
}

async fn projected_state<T>(&self, plugin_id: &str) -> Option<T>
where
    T: serde::de::DeserializeOwned,
{
    if let Some(value) = self.get_state(plugin_id).await {
        if let Ok(json) = serde_json::to_value(value) {
            if let Ok(state) = serde_json::from_value(json) {
                return Some(state);
            }
        }
    }

    let mut bytes = op_core::projection_shm::read_projection_bytes(plugin_id)?;
    let value = simd_json::to_owned_value(&mut bytes).ok()?;
    let json = serde_json::to_value(&value).ok()?;
    let state = serde_json::from_value(json).ok()?;
    self.update_state_cache(plugin_id.to_string(), value).await;
    Some(state)
}

fn broadcast_method_signal(
    &self,
    method_change: &StateChange,
    signal_name: &str,
    payload: &serde_json::Value,
) {
    let mut bytes = serde_json::to_vec(payload).unwrap_or_default();
    let payload =
        simd_json::to_owned_value(&mut bytes).unwrap_or_else(|_| simd_json::json!(null));
    let signal = StateChange {
        change_id: uuid::Uuid::new_v4().to_string(),
        event_id: method_change.event_id,
        plugin_id: method_change.plugin_id.clone(),
        object_path: method_change.object_path.clone(),
        change_type: ChangeType::Signal,
        member_name: Some(signal_name.to_string()),
        old_value: None,
        new_value: payload,
        tags_touched: method_change.tags_touched.clone(),
        event_hash: method_change.event_hash.clone(),
        timestamp: method_change.timestamp,
        actor_id: method_change.actor_id.clone(),
        source: method_change.source,
    };
    let _ = self.change_tx.send(signal);
}

async fn persist_zeroclaw_mutation(
    &self,
    method: &str,
    result: &serde_json::Value,
) -> anyhow::Result<()> {
    match method {
        "SetProvider" | "SetModel" => {
            self.merge_into_state_cache("zeroclaw", result).await;
        }
        "SetOvsRoutingModel"
        | "SetObfuscationModel"
        | "SetVectorizationModel"
        | "SetQdrantRetrievalModel"
        | "SetCozoRetrievalModel" => {
            self.merge_nested_into_state_cache("zeroclaw", "model_assignments", result)
                .await;
        }
        _ => {}
    }

    self.publish_plugin_projection_from_cache("zeroclaw", ChangeType::PropertySet)
        .await
}

/// Merge a flat JSON object of changed fields into the authoritative
/// in-memory state cache for `plugin_id` (used to persist Zeroclaw `Set*`
/// selection changes so readers observe the new effective state).
async fn merge_into_state_cache(&self, plugin_id: &str, changes: &serde_json::Value) {
    let changes_obj = match changes.as_object() {
        Some(o) => o,
        None => return,
    };
    let mut current = self
        .get_state(plugin_id)
        .await
        .and_then(|v| serde_json::to_value(&v).ok())
        .unwrap_or_else(|| serde_json::json!({}));
    if let Some(cur_obj) = current.as_object_mut() {
        for (k, v) in changes_obj {
            cur_obj.insert(k.clone(), v.clone());
        }
    }
    let mut bytes = serde_json::to_vec(&current).unwrap_or_default();
    if let Ok(owned) = simd_json::to_owned_value(&mut bytes) {
        self.update_state_cache(plugin_id.to_string(), owned).await;
    }

//!
//! `OvsdbDbusClient` (name kept for call-site compatibility) talks to
//! `ovsdb-server` natively via the vendor `rovs_ovsdb::Client` — no D-Bus hop.
//! The dead raw JSON-RPC D-Bus proxy was removed; compatibility callers enter
//! through the schema-declared `ovsdb_bridge` object on the canonical plugin
//! tree, while the audited bridge backend uses this native client.
//!
//! NOTE: the OpenFlow passthrough half of this module (`RovsOpenFlow`,
//! `openflow_proxy`, `ensure_proxies`) was removed along with
//! `op-openvswitch-daemon` (deprecated, purged — see CLAUDE.md). OpenFlow
//! control now runs entirely through `op-network::openflow::OpenFlowClient`
//! (direct TCP, no D-Bus hop) and the passive `op-of-controller` service in
//! `crates/op-network/src/controller.rs` — the same pattern OVSDB now follows.

use anyhow::{Context, Result};
use std::sync::Arc;

// ── OvsdbDbusClient ─────────────────────────────────────────────────────────

/// Default OVSDB socket address, in `rovs_transport::Address` syntax, matching
/// `ovs_capabilities.rs`'s `ovsdb_socket_path`.
const DEFAULT_OVSDB_ADDR: &str = "unix:/var/run/openvswitch/db.sock";

/// High-level OVSDB client — wraps the real vendor `rovs_ovsdb::Client`
/// (crates.io `rovs-ovsdb`, already a workspace dependency and already used
/// natively — no D-Bus hop — by `op-network::openflow` via `rovs_openflow`/
/// `rovs_transport`). No separate D-Bus passthrough daemon exists for OVSDB;
/// one here would (and did, before this fix) target a service that was never
/// built. `rovs_ovsdb::Client` needs `&mut self`, so the connection is held
/// behind a mutex and shared/reconnected lazily.
#[derive(Clone, Default)]
pub struct OvsdbDbusClient {
    client: Arc<tokio::sync::Mutex<Option<rovs_ovsdb::Client>>>,
}

impl OvsdbDbusClient {
    /// Kept sync to preserve the existing construction call sites; the vendor
    /// client connects lazily on first use.
    pub fn new() -> Self {
        Self {
            client: Arc::new(tokio::sync::Mutex::new(None)),
        }
    }

    /// Run `f` against a connected client, reconnecting once on failure (the
    /// socket may have been idle-closed by `ovsdb-server` between calls).
    async fn with_client<T, F>(&self, f: F) -> Result<T>
    where
        F: for<'a> Fn(
            &'a mut rovs_ovsdb::Client,
        ) -> std::pin::Pin<
            Box<dyn std::future::Future<Output = Result<T>> + Send + 'a>,
        >,
    {
        let addr =
            std::env::var("OVSDB_SOCKET_ADDR").unwrap_or_else(|_| DEFAULT_OVSDB_ADDR.to_string());
        let mut guard = self.client.lock().await;
        if guard.is_none() {
            let client = rovs_ovsdb::Client::connect(&addr)
                .await
                .with_context(|| format!("failed to connect to OVSDB at {addr}"))?;
            *guard = Some(client);
        }
        match f(guard.as_mut().expect("just ensured Some")).await {
            Ok(val) => Ok(val),
            Err(_first_err) => {
                // Reconnect once and retry — covers idle-closed sockets.
                let client = rovs_ovsdb::Client::connect(&addr)
                    .await
                    .with_context(|| format!("failed to reconnect to OVSDB at {addr}"))?;
                *guard = Some(client);
                f(guard.as_mut().expect("just ensured Some")).await
            }
        }
    }

    // ── Internal: build & send a transact ───────────────────────────────

    async fn transact_one(&self, op: serde_json::Value) -> Result<serde_json::Value> {
        // rovs_ovsdb::Client::transact() prepends the configured database name
        // itself, so operations here are passed WITHOUT it (unlike the raw
        // JSON-RPC ["Open_vSwitch", op, ...] wire shape).
        let result = self
            .with_client(move |client| {
                let op = op.clone();
                Box::pin(async move {
                    client
                        .transact(serde_json::Value::Array(vec![op]))
                        .await
                        .context("OVSDB transact failed")
                })
            })
            .await?;
        // RFC 7047: `result` is an array of one entry per input operation, in
        // order. Callers of transact_one all expect the single op's result
        // object directly (e.g. `result.get("rows")`), so unwrap here once
        // rather than in every caller.
        Self::check_errors(&result)?;
        Ok(result
            .as_array()
            .and_then(|a| a.first())
            .cloned()
            .unwrap_or(serde_json::Value::Null))
    }

    async fn transact_many(&self, ops: Vec<serde_json::Value>) -> Result<serde_json::Value> {
        self.with_client(move |client| {
            let ops = ops.clone();
            Box::pin(async move {
                client
                    .transact(serde_json::Value::Array(ops))
                    .await
                    .context("OVSDB transact failed")
            })
        })
        .await
    }

    // ── Read helpers ──────────────────────────────────────────────────────

    /// Return `true` if the daemon (and OVSDB) is reachable.
    pub async fn list_dbs(&self) -> Result<Vec<String>> {
        let val = self
            .with_client(|client| {
                Box::pin(async move { client.list_dbs().await.context("OVSDB list_dbs failed") })
            })
            .await?;
        Ok(val)
    }

    /// Return the schema cached by the connected vendor client.
    pub async fn get_schema(&self) -> Result<serde_json::Value> {
        self.with_client(|client| {
            Box::pin(async move {
                let schema = client
                    .schema()
                    .ok_or_else(|| anyhow::anyhow!("OVSDB schema is not loaded"))?;
                serde_json::to_value(schema).context("serialize OVSDB schema")
            })
        })
        .await
    }

    /// Return `true` if a bridge with the given name exists.
    pub async fn bridge_exists(&self, bridge_name: &str) -> Result<bool> {
        let result = self
            .transact_one(serde_json::json!({
                "op": "select",
                "table": "Bridge",
                "where": [["name", "==", bridge_name]],
                "columns": ["_uuid"]
            }))
            .await?;
        Ok(result
            .get("rows")
            .and_then(|r| r.as_array())
            .map(|a| !a.is_empty())
            .unwrap_or(false))
    }

    /// Return the names of all bridges.
    pub async fn list_bridges(&self) -> Result<Vec<String>> {
        let result = self
            .transact_one(serde_json::json!({
                "op": "select",
                "table": "Bridge",
                "where": [],
                "columns": ["name"]
            }))
            .await?;
        Ok(result
            .get("rows")
            .and_then(|r| r.as_array())
            .cloned()
            .unwrap_or_default()
            .iter()
            .filter_map(|r| r.get("name").and_then(|v| v.as_str()).map(String::from))
            .collect())
    }

    /// Return the names of all ports on a bridge.
    pub async fn list_bridge_ports(&self, bridge_name: &str) -> Result<Vec<String>> {
        let bridge_result = self
            .transact_one(serde_json::json!({
                "op": "select",
                "table": "Bridge",
                "where": [["name", "==", bridge_name]],
                "columns": ["ports"]
            }))
            .await?;
        let bridge_rows = bridge_result.get("rows").and_then(|r| r.as_array());
        let port_uuids: Vec<String> = match bridge_rows {
            Some(rows) if !rows.is_empty() => {
                let mut uuids = Vec::new();
                if let Some(ports) = rows[0].get("ports") {
                    Self::collect_uuids(ports, &mut uuids);
                }
                uuids
            }
            _ => return Ok(Vec::new()),
        };

        let mut names = Vec::new();
        for uuid in port_uuids {
            let result = self
                .transact_one(serde_json::json!({
                    "op": "select",
                    "table": "Port",
                    "where": [["_uuid", "==", ["uuid", uuid]]],
                    "columns": ["name"]
                }))
                .await?;
            if let Some(row) = result
                .get("rows")
                .and_then(|r| r.as_array())
                .and_then(|a| a.first())
            {
                if let Some(n) = row.get("name").and_then(|v| v.as_str()) {
                    names.push(n.to_string());
                }
            }
        }
        Ok(names)
    }

    /// Return the raw JSON row for a bridge.
    pub async fn get_bridge_info(&self, bridge_name: &str) -> Result<String> {
        let result = self
            .transact_one(serde_json::json!({
                "op": "select",
                "table": "Bridge",
                "where": [["name", "==", bridge_name]],
                "columns": []
            }))
            .await?;
        Ok(serde_json::to_string_pretty(&result)?)
    }

    // ── Mutation helpers ──────────────────────────────────────────────────

    /// Create a bridge if it does not exist.
    pub async fn create_bridge(&self, bridge_name: &str) -> Result<()> {
        if self.bridge_exists(bridge_name).await? {
            log::info!("Bridge {} already exists, skipping creation", bridge_name);
            return Ok(());
        }
        let ops = vec![
            serde_json::json!({
                "op": "insert",
                "table": "Bridge",
                "row": { "name": bridge_name, "stp_enable": false },
                "uuid-name": "new_bridge"
            }),
            serde_json::json!({
                "op": "mutate",
                "table": "Open_vSwitch",
                "where": [],
                "mutations": [["bridges", "insert", ["named-uuid", "new_bridge"]]]
            }),
        ];

