/// Move an existing host link into the network namespace owned by `netns_pid`.
pub async fn move_link_to_netns(ifname: &str, netns_pid: u32) -> Result<()> {
    if netns_pid == 0 {
        anyhow::bail!("network namespace PID must be greater than zero");
    }
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);
    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .with_context(|| format!("interface '{ifname}' not found"))?;
    handle
        .link()
        .set(link.header.index)
        .setns_by_pid(netns_pid)
        .execute()
        .await
        .with_context(|| format!("move interface '{ifname}' to netns PID {netns_pid}"))
}

pub async fn add_ipv4_address_in_netns(
    netns_pid: u32,
    ifname: &str,
    ip: &str,
    prefix: u8,
) -> Result<()> {
    let ifname = ifname.to_string();
    let ip = ip.to_string();
    in_network_namespace(netns_pid, move || async move {
        add_ipv4_address(&ifname, &ip, prefix).await
    })
    .await
}

pub async fn set_link_state_in_netns(
    netns_pid: u32,
    ifname: &str,
    is_up: bool,
) -> Result<()> {
    let ifname = ifname.to_string();
    in_network_namespace(netns_pid, move || async move {
        if is_up {
            link_up(&ifname).await
        } else {
            link_down(&ifname).await
        }
    })
    .await
}

pub async fn add_default_route_in_netns(
    netns_pid: u32,
    ifname: &str,
    gateway: &str,
) -> Result<()> {
    let ifname = ifname.to_string();
    let gateway = gateway.to_string();
    in_network_namespace(netns_pid, move || async move {
        add_default_route(&ifname, &gateway).await
    })
    .await
}

/// Add an IPv4 route in the current namespace through native rtnetlink.
pub async fn add_ipv4_route(
    destination: &str,
    gateway: Option<&str>,
    ifname: &str,
