    pub actions: ActionList,
    /// Instructions (OF 1.3+, takes precedence over actions if set)
    pub instructions: InstructionList,
    /// Idle timeout
    pub idle_timeout: u16,
    /// Hard timeout
    pub hard_timeout: u16,
    /// Flags
    pub flags: FlowFlags,
