content.data:
/// |                                                               |
/// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
/// |                        cookie_mask                           |
/// |                                                               |
/// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
/// |                       match (variable)                       |
/// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
/// ```
#[derive(Debug, Clone)]
pub struct FlowStatsRequest {
    /// Table ID (0xff for all tables)
    pub table_id: u8,
    /// Output port filter (OFPP_ANY for any)
    pub out_port: u32,
    /// Output group filter (OFPG_ANY for any)
    pub out_group: u32,
    /// Cookie filter
    pub cookie: u64,
    /// Cookie mask (0 to match all cookies)
    pub cookie_mask: u64,
    /// Match fields filter
    pub match_fields: Match,
}

impl Default for FlowStatsRequest {
    fn default() -> Self {
        Self::new()
    }
}

impl FlowStatsRequest {
    /// Create a new flow stats request that matches all flows.
    pub fn new() -> Self {
        Self {
            table_id: 0xff,   // All tables
            out_port: OFPP_ANY,
            out_group: OFPP_ANY, // OFPG_ANY has same value
            cookie: 0,
            cookie_mask: 0,   // Match all cookies
            match_fields: Match::new(),
        }
    }

    /// Filter by table ID.
    pub fn table(mut self, table_id: u8) -> Self {
        self.table_id = table_id;
        self
    }

    /// Filter by match fields.
    pub fn match_fields(mut self, m: Match) -> Self {
        self.match_fields = m;
        self
    }

    /// Filter by cookie.
    pub fn cookie(mut self, cookie: u64, mask: u64) -> Self {
        self.cookie = cookie;
        self.cookie_mask = mask;
        self
    }

    /// Encode the flow stats request body.
    pub fn encode(&self) -> Vec<u8> {
        let match_bytes = self.match_fields.encode();
        let mut buf = Vec::with_capacity(32 + match_bytes.len());

        // table_id (1) + pad (3)
        buf.push(self.table_id);
        buf.extend([0u8; 3]);

        // out_port (4)
        buf.extend(self.out_port.to_be_bytes());

        // out_group (4)
        buf.extend(self.out_group.to_be_bytes());

        // pad (4)
        buf.extend([0u8; 4]);

        // cookie (8)
        buf.extend(self.cookie.to_be_bytes());

        // cookie_mask (8)
        buf.extend(self.cookie_mask.to_be_bytes());

        // match (variable)
        buf.extend(match_bytes);

        buf
    }

    /// Create the complete multipart request message.
    pub fn to_message(&self, version: Version, xid: u32) -> Message {
        let header = MultipartHeader {
            mp_type: MultipartType::Flow,
            flags: 0,
        };

        let mut body = Vec::new();
        body.extend(header.encode());
        body.extend(self.encode());

        Message::new(version, MessageType::MultipartRequest, xid, Bytes::from(body))
    }
}

/// Individual flow statistics from a FlowStats reply.
///
/// ```text
/// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
/// |           length            |   table_id  |      pad        |
/// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
/// |                         duration_sec                         |
/// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
/// |                        duration_nsec                         |
/// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
/// |           priority          |         idle_timeout           |
/// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
/// |         hard_timeout        |            flags               |
/// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
/// |                           pad (4)                            |
/// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
/// |                           cookie                             |
/// |                                                               |
/// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
/// |                        packet_count                          |
/// |                                                               |
/// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
/// |                         byte_count                           |
/// |                                                               |
/// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
/// |                       match (variable)                       |
/// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
/// |                   instructions (variable)                    |
/// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
/// ```
#[derive(Debug, Clone)]
pub struct FlowStatsEntry {
    /// Table ID
    pub table_id: u8,
    /// Time flow has been alive (seconds)
    pub duration_sec: u32,
    /// Time flow has been alive (nanoseconds beyond duration_sec)
    pub duration_nsec: u32,
    /// Priority
    pub priority: u16,
    /// Idle timeout
    pub idle_timeout: u16,
    /// Hard timeout
    pub hard_timeout: u16,
    /// Flags
    pub flags: u16,
    /// Cookie
    pub cookie: u64,
    /// Packet count
    pub packet_count: u64,
    /// Byte count
    pub byte_count: u64,
    /// Match fields
    pub match_fields: Match,
    /// Instructions (raw bytes for now)
    pub instructions: Vec<u8>,
}

impl FlowStatsEntry {
    /// Fixed header size before match (48 bytes).
    pub const FIXED_SIZE: usize = 48;

    /// Parse a single flow stats entry from bytes.
    #[allow(clippy::similar_names)]
    pub fn decode(data: &[u8]) -> crate::Result<(Self, usize)> {
        if data.len() < Self::FIXED_SIZE {
            return Err(crate::Error::Parse("flow stats entry too short".into()));
        }

        let length = u16::from_be_bytes([data[0], data[1]]) as usize;
        if data.len() < length {
            return Err(crate::Error::Parse("flow stats entry truncated".into()));
        }

        let table_id = data[2];
        // data[3] is padding
        let duration_sec = u32::from_be_bytes([data[4], data[5], data[6], data[7]]);
        let duration_nsec = u32::from_be_bytes([data[8], data[9], data[10], data[11]]);
        let priority = u16::from_be_bytes([data[12], data[13]]);
        let idle_timeout = u16::from_be_bytes([data[14], data[15]]);
        let hard_timeout = u16::from_be_bytes([data[16], data[17]]);
        let flags = u16::from_be_bytes([data[18], data[19]]);
        // data[20..24] is padding
        let cookie = u64::from_be_bytes([
            data[24], data[25], data[26], data[27],
            data[28], data[29], data[30], data[31],
        ]);
        let packet_count = u64::from_be_bytes([
            data[32], data[33], data[34], data[35],
            data[36], data[37], data[38], data[39],
        ]);
        let byte_count = u64::from_be_bytes([
            data[40], data[41], data[42], data[43],
            data[44], data[45], data[46], data[47],
        ]);

        // Parse match
        let match_data = &data[Self::FIXED_SIZE..];
        let (match_fields, match_len) = Match::decode(match_data)?;

        // Instructions follow the match
        let instructions_start = Self::FIXED_SIZE + match_len;
        let instructions = data[instructions_start..length].to_vec();

        Ok((
            Self {
                table_id,
                duration_sec,
                duration_nsec,
                priority,
                idle_timeout,
                hard_timeout,
                flags,
                cookie,
                packet_count,
                byte_count,
                match_fields,
                instructions,
            },
            length,
        ))
    }

        // Skip other async messages
    }
}

/// Dump all flows from the switch.
///
/// Returns all flow entries from all tables. Use `dump_flows_filtered`
/// for more specific queries.
pub async fn dump_flows(&mut self) -> Result<Vec<FlowStatsEntry>> {
    self.dump_flows_filtered(FlowStatsRequest::new()).await
}

/// Dump flows matching the given filter.
///
/// The request can filter by table ID, match fields, cookie, etc.
pub async fn dump_flows_filtered(
    &mut self,
    request: FlowStatsRequest,
) -> Result<Vec<FlowStatsEntry>> {
    let xid = self.next_xid();
    let msg = request.to_message(self.version, xid);
    self.send_message(&msg).await?;

    let mut all_entries = Vec::new();

    // Receive multipart replies until we get one without MORE flag
    loop {
        let reply = self.recv_message().await?;

        // Check for errors
        Self::check_error(&reply)?;

        // Handle echo requests
        if reply.header.msg_type == MessageType::EchoRequest {
            let echo_reply = Message::new(
                self.version,
                MessageType::EchoReply,
                reply.header.xid,
                reply.body.clone(),
            );
            self.send_message(&echo_reply).await?;
            continue;
        }

        // Skip non-multipart replies
        if reply.header.msg_type != MessageType::MultipartReply {
            continue;
        }

        // Parse the flow stats reply
        let (entries, has_more) = parse_flow_stats_reply(&reply.body)?;
        all_entries.extend(entries);

        if !has_more {
            break;
        }
    }

    Ok(all_entries)
}

/// Wait for and receive a Packet-In message.
///
/// This blocks until a Packet-In message is received, handling
/// echo requests and skipping other message types.
pub async fn recv_packet_in(&mut self) -> Result<PacketIn> {
    loop {
        let msg = self.recv_message().await?;

        // Check for errors
        Self::check_error(&msg)?;

        // Handle echo requests (keep-alive)
        if msg.header.msg_type == MessageType::EchoRequest {
            let echo_reply = Message::new(
                self.version,
                MessageType::EchoReply,
                msg.header.xid,
                msg.body.clone(),
            );
            self.send_message(&echo_reply).await?;
            continue;
        }

        // Process Packet-In
        if msg.header.msg_type == MessageType::PacketIn {
            return PacketIn::parse(msg.body);
        }

        // Skip other async messages (PortStatus, FlowRemoved)
    }
}

