        "name".to_string(),
        FieldSchema {
            read_only: true,
            ..field(
                FieldType::String,
                true,
                "Incus instance name",
                None,
                Some(json!("netmaker")),
            )
        },
    );
    fields.insert(
        "image".to_string(),
        field(
            FieldType::String,
            false,
            "OCI image reference",
            None,
            Some(json!("docker:gravitl/netmaker:v1.5.1")),
        ),
    );
    fields.insert(
        "loopback_required".to_string(),
        field(
            FieldType::Boolean,
            false,
            "Bring loopback UP before attached services start",
            Some(json!(false)),
            Some(json!(true)),
        ),
