/// Rename network interface
pub async fn link_set_name(old_name: &str, new_name: &str) -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    // Find interface by current name
    let mut links = handle
        .link()
        .get()
        .match_name(old_name.to_string())
        .execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", old_name))?;

    let ifindex = link.header.index;

    // Set new name
    handle
        .link()
        .set(ifindex)
        .name(new_name.to_string())
        .execute()
        .await
        .context(format!("Failed to rename {} to {}", old_name, new_name))?;

    Ok(())
}

/// Move an existing host link into the network namespace owned by `netns_pid`.
pub async fn move_link_to_netns(ifname: &str, netns_pid: u32) -> Result<()> {
    if netns_pid == 0 {
        anyhow::bail!("network namespace PID must be greater than zero");
    }
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);
    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .with_context(|| format!("interface '{ifname}' not found"))?;
    handle
        .link()
        .set(link.header.index)
        .setns_by_pid(netns_pid)
        .execute()
        .await
        .with_context(|| format!("move interface '{ifname}' to netns PID {netns_pid}"))
}

