        let instruction_bytes = if self.instructions.is_empty() && !self.actions.is_empty() {
            // Wrap actions in ApplyActions instruction
            let inst = Instruction::ApplyActions(self.actions.clone());
            inst.encode()
        } else {
            self.instructions.encode()
        };

