            "fin" => 0x001,
            "syn" => 0x002,
            "rst" => 0x004,
            "psh" => 0x008,
            "ack" => 0x010,
            "urg" => 0x020,
            "ece" => 0x040,
            "cwr" => 0x080,
            "ns" => 0x100,
            other => bail!("unknown tcp_flags token '+{}' in '{}'", other, s),
        };
    }
    Ok(flags)
}

