    async fn verify_state(&self, desired: &Value) -> Result<bool> {
        let desired: OpenFlowConfig = simd_json::serde::from_owned_value(desired.clone())?;
        for bridge in &desired.bridges {
            let live = self.query_flows(&bridge.name).await?;
            for flow in &bridge.flows {
                let normalized = self.normalize_flow_for_bridge(&bridge.name, flow).await?;
                if !live.iter().any(|current| current == &normalized) {
                    return Ok(false);
                }
            }
        }
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        let current_state = simd_json::json!(null);

        Ok(Checkpoint {
            id: format!("openflow_{}", chrono::Utc::now().timestamp()),
            plugin: "openflow".to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: current_state,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, checkpoint: &Checkpoint) -> Result<()> {
        log::info!(
            "Rolling back OpenFlow to checkpoint from {}",
            checkpoint.timestamp
        );

        let current = simd_json::json!(null);
        let diff = self
            .calculate_diff(&current, &checkpoint.state_snapshot)
            .await?;

        self.apply_state(&diff).await?;

        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: true,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false, // Flows installed one by one
        }
    }
}

