mod remote_operation_client_tests {
    use super::*;

    #[test]
    fn legacy_constructor_keeps_addresses_equal() {
        let client = RemoteOperationClient::new(
            Arc::new(GrpcClientPool::new()),
            "http://127.0.0.1:8090",
            "test",
        );
        assert_eq!(client.default_address, "http://127.0.0.1:8090");
        assert_eq!(client.netmaker_address, client.default_address);
    }

    #[test]
    fn explicit_constructor_separates_netmaker_endpoint() {
        let client = RemoteOperationClient::new_with_netmaker_address(
            Arc::new(GrpcClientPool::new()),
            "http://127.0.0.1:8090",
            "http://127.0.0.1:50061",
            "test",
        );
        assert_eq!(client.default_address, "http://127.0.0.1:8090");
        assert_eq!(client.netmaker_address, DEFAULT_NETMAKER_ADAPTER_ADDR);
    }

    #[test]
    fn builder_changes_only_netmaker_endpoint() {
        let client = RemoteOperationClient::new(
            Arc::new(GrpcClientPool::new()),
            "http://127.0.0.1:8090",
            "test",
        )
        .with_netmaker_address("http://127.0.0.1:50061");
        assert_eq!(client.default_address, "http://127.0.0.1:8090");
        assert_eq!(client.netmaker_address, DEFAULT_NETMAKER_ADAPTER_ADDR);
    }

    #[test]
    fn every_netmaker_rpc_uses_dedicated_address_and_metadata() {
        let source = include_str!("grpc_client.rs");
        let block = source
            .split("/// Join a Netmaker network through the Netmaker adapter gRPC service.")
            .nth(1)
            .expect("Netmaker RPC implementation block")
            .split("#[cfg(test)]\nmod remote_operation_client_tests")
            .next()
            .expect("production Netmaker RPC block");
        assert_eq!(
            block
                .matches("netmaker_client(&self.netmaker_address)")
                .count(),
            8
        );
        assert_eq!(block.matches("authenticated_netmaker_request!").count(), 8);
        assert!(!block.contains("netmaker_client(&self.default_address)"));
        assert!(!block.contains("Request::new("));
    }
}

