//! bootstrap (loopback, OVS internal port, namespace address, and routes).
//!
//! Lifecycle remains owned by Incus/runit. This plugin owns only the declared
//! attachment and resolves the running instance PID immediately before every
//! namespace transaction.

use anyhow::{Context, Result};
use op_state::{
    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
};
use op_state_store::{FieldSchema, FieldType, PluginSchema};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use simd_json::json;
use simd_json::prelude::*;
use simd_json::OwnedValue as Value;
use std::collections::HashMap;

// ── Typed state ──────────────────────────────────────────────────────────────

#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq)]
pub struct OciState {
    #[serde(default)]
    pub containers: Vec<OciContainerConfig>,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq)]
pub struct OciContainerConfig {
    pub name: String,
    #[serde(default)]
    pub image: String,
    #[serde(default)]
    pub loopback_required: bool,
    #[serde(default)]
    pub entrypoint_override: Option<String>,
    #[serde(default)]
    pub privileged: bool,
    #[serde(default)]
    pub env: HashMap<String, String>,
    #[serde(default)]
    pub sockets: Vec<serde_json::Value>,
    #[serde(default)]
    pub volumes: Vec<serde_json::Value>,
    #[serde(default)]
    pub port_attach: Option<PortAttachConfig>,
    #[serde(default)]
    pub grpc_adapter: Option<GrpcAdapterConfig>,
    #[serde(default)]
    pub supervision: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, JsonSchema)]
pub struct PortAttachConfig {
    pub bridge: String,
    pub port_name: String,
    #[serde(default)]
    pub ip_addrs: Vec<String>,
    pub gateway: String,
    #[serde(default)]
    pub routes: Vec<PortRouteConfig>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, JsonSchema)]
pub struct PortRouteConfig {
    pub destination: String,
    #[serde(default)]
    pub gateway: Option<String>,
    #[serde(default)]
    pub table: Option<u32>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, JsonSchema)]
pub struct GrpcAdapterConfig {
    pub binary: String,
    pub socket: String,
    pub host_endpoint: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct AttachmentActionConfig {
    container_name: String,
    loopback_required: bool,
    port_attach: PortAttachConfig,
}

// ── Schema definition — THE PLUGIN IS THE SCHEMA ───────────────────────────

fn field(
    field_type: FieldType,
    required: bool,
    description: &str,
    default: Option<Value>,
    example: Option<Value>,
) -> FieldSchema {
    FieldSchema {
        field_type,
        required,
        description: description.to_string(),
        default,
        example,
        constraints: Vec::new(),
        read_only: false,
        read_only_when: None,
    }
}

fn route_fields() -> HashMap<String, FieldSchema> {
    HashMap::from([
        (
            "destination".to_string(),
            field(
                FieldType::String,
                true,
                "IPv4 destination in CIDR notation",
                None,
                Some(json!("10.10.0.0/16")),
            ),
        ),
        (
            "gateway".to_string(),
            field(
                FieldType::String,
                false,
                "Optional IPv4 next hop",
                None,
                Some(json!("10.200.1.2")),
            ),
        ),
        (
            "table".to_string(),
            field(
                FieldType::Integer,
                false,
                "Optional route table number",
                None,
                Some(json!(254)),
            ),
        ),
    ])
}

fn port_attach_fields() -> HashMap<String, FieldSchema> {
    HashMap::from([
        (
            "bridge".to_string(),
            field(
                FieldType::String,
                true,
                "Existing OVS bridge",
                None,
                Some(json!("ovsbr0")),
            ),
        ),
        (
            "port_name".to_string(),
            field(
                FieldType::String,
                true,
                "OVS internal port name",
                None,
                Some(json!("netmk")),
            ),
        ),
        (
            "ip_addrs".to_string(),
            field(
                FieldType::Array(Box::new(FieldType::String)),
                false,
                "IPv4 addresses assigned inside the container namespace",
                Some(json!([])),
                Some(json!(["10.200.1.1/30"])),
            ),
        ),
        (
            "gateway".to_string(),
            field(
                FieldType::String,
                true,
                "Default IPv4 gateway inside the namespace",
                None,
                Some(json!("10.200.1.2")),
            ),
        ),
        (
            "routes".to_string(),
            field(
                FieldType::Array(Box::new(FieldType::Object(route_fields()))),
                false,
                "Additional namespace-local IPv4 routes",
                Some(json!([])),
                Some(json!([])),
            ),
        ),
    ])
}

fn grpc_adapter_fields() -> HashMap<String, FieldSchema> {
    HashMap::from([
        (
            "binary".to_string(),
            field(
                FieldType::String,
                true,
                "Adapter binary supervised inside the container",
                None,
                Some(json!("op-grpc-adapters")),
            ),
        ),
        (
            "socket".to_string(),
            field(
                FieldType::String,
                true,
                "Bind-mounted adapter Unix socket",
                None,
                Some(json!(
                    "/var/lib/opdbus-runtime/netmaker/op-grpc-adapters.sock"
                )),
            ),
        ),
        (
            "host_endpoint".to_string(),
            field(
                FieldType::String,
                true,
                "Dedicated host loopback endpoint",
                None,
                Some(json!("http://127.0.0.1:50061")),
            ),
        ),
    ])
}

fn oci_container_fields() -> HashMap<String, FieldSchema> {
    let mut fields = HashMap::new();
    fields.insert(
        "name".to_string(),
        FieldSchema {
            read_only: true,
            ..field(
                FieldType::String,
                true,
                "Incus instance name",
                None,
                Some(json!("netmaker")),
            )
        },
    );
    fields.insert(
        "image".to_string(),
        field(
            FieldType::String,
            false,
            "OCI image reference",
            None,
            Some(json!("docker:gravitl/netmaker:v1.5.1")),
        ),
    );
    fields.insert(
        "loopback_required".to_string(),

        "loopback_required".to_string(),
        field(
            FieldType::Boolean,
            false,
            "Bring loopback UP before attached services start",
            Some(json!(false)),
            Some(json!(true)),
        ),
    );
    fields.insert(
        "entrypoint_override".to_string(),
        field(
            FieldType::String,
            false,
            "Optional OCI entrypoint wrapper",
            None,
            None,
        ),
    );
    fields.insert(
        "privileged".to_string(),
        field(
            FieldType::Boolean,
            false,
            "Whether the container runs privileged",
            Some(json!(false)),
            Some(json!(true)),
        ),
    );
    fields.insert(
        "env".to_string(),
        field(
            FieldType::Any,
            false,
            "Container environment variables",
            Some(json!({})),
            None,
        ),
    );
    fields.insert(
        "sockets".to_string(),
        field(
            FieldType::Array(Box::new(FieldType::Any)),
            false,
            "Incus proxy socket devices",
            Some(json!([])),
            None,
        ),
    );
    fields.insert(
        "volumes".to_string(),
        field(
            FieldType::Array(Box::new(FieldType::Any)),
            false,
            "Incus volume devices",
            Some(json!([])),
            None,
        ),
    );
    fields.insert(
        "port_attach".to_string(),
        field(
            FieldType::Object(port_attach_fields()),
            false,
            "Typed OVS internal-port attachment reconciled into the current container netns",
            None,
            Some(json!({
                "bridge": "ovsbr0",
                "port_name": "netmk",
                "ip_addrs": ["10.200.1.1/30"],
                "gateway": "10.200.1.2",
                "routes": []
            })),
        ),
    );
    fields.insert(
        "grpc_adapter".to_string(),
        field(
            FieldType::Object(grpc_adapter_fields()),
            false,
            "Dedicated adapter UDS and host endpoint",
            None,
            None,
        ),
    );
    fields.insert(
        "supervision".to_string(),
        field(
            FieldType::String,
            false,
            "Container feature supervisor (runit only)",
            Some(json!("runit")),
            Some(json!("runit")),
        ),
    );
    fields
}

/// Input struct for pulling an OCI image.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct PullImageInput {
    pub image: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct RunContainerInput {
    pub name: String,
    pub image: String,
    #[serde(default)]
    pub loopback_required: bool,
    #[serde(default)]
    pub privileged: bool,
    #[serde(default)]
    pub env: HashMap<String, String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct CreateContainerInput {
    pub id: String,
    pub bundle_path: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct StartContainerInput {
    pub id: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct KillContainerInput {
    pub id: String,
    pub signal: Option<i32>,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct DeleteContainerInput {
    pub id: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct GetContainerStateInput {
    pub id: String,
}

pub(crate) fn oci_schema() -> PluginSchema {
    PluginSchema::builder("oci")
        .category("container")
        .version("1.0.0")
        .description("OCI lifecycle declarations and native OVS/netns port attachment")
        .dependency("incus")
        .dependency("rovs_commands")
        .dependency("rtnetlink")
        .array_field(
            "containers",
            FieldType::Object(oci_container_fields()),
            true,
            "Declared OCI containers with lifecycle and attachment config",
        )
        .example(json!({
            "containers": [{
                "name": "netmaker",
                "image": "docker:gravitl/netmaker:v1.5.1",
                "loopback_required": true,
                "port_attach": {
                    "bridge": "ovsbr0",
                    "port_name": "netmk",
                    "ip_addrs": ["10.200.1.1/30"],
                    "gateway": "10.200.1.2",
                    "routes": []
                },
                "grpc_adapter": {
                    "binary": "op-grpc-adapters",
                    "socket": "/var/lib/opdbus-runtime/netmaker/op-grpc-adapters.sock",
                    "host_endpoint": "http://127.0.0.1:50061"
                },
                "supervision": "runit"
            }]
        }))
        .method(
            super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<
                PullImageInput,
                super::plugin_scaffold_helpers::AckOutput,
            >(
                "pull_image",
                op_state_store::SideEffect::Mutation,
                false,
                "cap.container.oci.image.pull@v1",
                "mut.container.oci.image.pull@v1",
            ),
        )
        .method(
            super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<
                RunContainerInput,
                super::plugin_scaffold_helpers::AckOutput,
            >(
                "run_container",
                op_state_store::SideEffect::Mutation,
                false,
                "cap.container.oci.run@v1",
                "mut.container.oci.run@v1",
            ),
        )
        .method(
            super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<
                CreateContainerInput,
                super::plugin_scaffold_helpers::AckOutput,
            >(
                "create",
                op_state_store::SideEffect::Mutation,
                false,
                "cap.container.oci.create@v1",
                "mut.container.oci.create@v1",
            ),
        )
        .method(
            super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<
                StartContainerInput,
                super::plugin_scaffold_helpers::AckOutput,
            >(
                "start",
                op_state_store::SideEffect::Mutation,
                false,
                "cap.container.oci.start@v1",
                "mut.container.oci.start@v1",
            ),
        )
        .method(
            super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<
                KillContainerInput,
                super::plugin_scaffold_helpers::AckOutput,
            >(
                "kill",
                op_state_store::SideEffect::Mutation,
                false,
                "cap.container.oci.kill@v1",
                "mut.container.oci.kill@v1",
            ),
        )
        .method(
            super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<
                DeleteContainerInput,
                super::plugin_scaffold_helpers::AckOutput,
            >(
                "delete",
                op_state_store::SideEffect::Mutation,
                false,
                "cap.container.oci.delete@v1",
                "mut.container.oci.delete@v1",
            ),
        )
        .method(
            super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<
                GetContainerStateInput,
                super::plugin_scaffold_helpers::AckOutput,
            >(
                "state",
                op_state_store::SideEffect::Read,
                true,
                "cap.container.oci.state.get@v1",
                "obs.container.oci.state.get@v1",
            ),
        )
        .build()
}

// ── Reconciliation ───────────────────────────────────────────────────────────

pub struct OciPlugin {
    ovsdb_client: op_network::rovs_proxy::OvsdbDbusClient,
}

impl Default for OciPlugin {
    fn default() -> Self {
        Self::new()
    }
}

impl OciPlugin {
    pub fn new() -> Self {
        Self {
            ovsdb_client: op_network::rovs_proxy::OvsdbDbusClient::new(),
        }
    }

    pub async fn reconcile_container_attachment(
        &self,
        container: &OciContainerConfig,
    ) -> Result<Vec<String>> {
        let attach = container
            .port_attach
            .clone()
            .with_context(|| format!("container '{}' has no port_attach", container.name))?;
        self.apply_attachment(&AttachmentActionConfig {
            container_name: container.name.clone(),
            loopback_required: container.loopback_required,
            port_attach: attach,
        })
        .await
    }

    pub async fn verify_container_attachment(

        &self,
        container: &OciContainerConfig,
    ) -> Result<bool> {
        let attach = container
            .port_attach
            .clone()
            .with_context(|| format!("container '{}' has no port_attach", container.name))?;
        self.verify_attachment(&AttachmentActionConfig {
            container_name: container.name.clone(),
            loopback_required: container.loopback_required,
            port_attach: attach,
        })
        .await
    }

    pub async fn delete_container_attachment(&self, container: &OciContainerConfig) -> Result<()> {
        let attach = container
            .port_attach
            .as_ref()
            .with_context(|| format!("container '{}' has no port_attach", container.name))?;
        self.ovsdb_client
            .delete_port(&attach.bridge, &attach.port_name)
            .await
    }

    fn state_from_value(value: &Value) -> Result<OciState> {
        if value.is_null() {
            return Ok(OciState::default());
        }
        simd_json::serde::from_owned_value(value.clone()).context("deserialize OCI state")
    }

    fn attachment_resource(container: &str, attach: &PortAttachConfig) -> String {
        format!(
            "{container}/port_attach/{}/{}",
            attach.bridge, attach.port_name
        )
    }

    fn already_exists(error: &anyhow::Error) -> bool {
        let text = format!("{error:#}").to_ascii_lowercase();
        text.contains("file exists") || text.contains("eexist") || text.contains("os error 17")
    }

    async fn interface_type(&self, port_name: &str) -> Result<Option<String>> {
        let operations = simd_json::json!([{
            "op": "select",
            "table": "Interface",
            "where": [["name", "==", port_name]],
            "columns": ["type"]
        }]);
        let response = self.ovsdb_client.transact_simd(operations).await?;
        Ok(response
            .as_array()
            .and_then(|entries| entries.first())
            .and_then(|entry| entry.get("rows"))
            .and_then(|rows| rows.as_array())
            .and_then(|rows| rows.first())
            .and_then(|row| row.get("type"))
            .and_then(|value| value.as_str())
            .map(str::to_string))
    }

    async fn ovs_attachment_ready(&self, attach: &PortAttachConfig) -> Result<bool> {
        let ports = self.ovsdb_client.list_bridge_ports(&attach.bridge).await?;
        if !ports.iter().any(|port| port == &attach.port_name) {
            return Ok(false);
        }
        Ok(self.interface_type(&attach.port_name).await?.as_deref() == Some("internal"))
    }

    async fn ensure_ovs_attachment(&self, attach: &PortAttachConfig) -> Result<Vec<String>> {
        let mut changes = Vec::new();
        let ports = self.ovsdb_client.list_bridge_ports(&attach.bridge).await?;
        if !ports.iter().any(|port| port == &attach.port_name) {
            self.ovsdb_client
                .add_port_with_type(&attach.bridge, &attach.port_name, Some("internal"))
                .await
                .with_context(|| {
                    format!(
                        "create OVS internal port {} on {}",
                        attach.port_name, attach.bridge
                    )
                })?;
            changes.push(format!(
                "created OVS internal port {} on {}",
                attach.port_name, attach.bridge
            ));
        }
        if self.interface_type(&attach.port_name).await?.as_deref() != Some("internal") {
            self.ovsdb_client
                .set_interface_type(&attach.port_name, "internal")
                .await?;
            changes.push(format!("set {} type=internal", attach.port_name));
        }
        Ok(changes)
    }

    async fn namespace_attachment_ready(
        &self,
        pid: u32,
        loopback_required: bool,
        attach: &PortAttachConfig,
    ) -> Result<bool> {
        let port_name = attach.port_name.clone();
        let (interfaces, routes) = op_network::rtnetlink::in_network_namespace(pid, move || {
            let port_name = port_name.clone();
            async move {
                let interfaces = op_network::rtnetlink::list_interfaces().await?;
                let routes = op_network::rtnetlink::list_routes_for_interface(&port_name).await?;
                Ok((interfaces, routes))
            }
        })
        .await?;

        if loopback_required
            && !interfaces
                .iter()
                .any(|interface| interface.name == "lo" && interface.state == "up")
        {
            return Ok(false);
        }
        let Some(interface) = interfaces
            .iter()
            .find(|interface| interface.name == attach.port_name)
        else {
            return Ok(false);
        };
        if interface.state != "up" {
            return Ok(false);
        }
        for cidr in &attach.ip_addrs {
            let (address, prefix) = op_network::rtnetlink::parse_ipv4_cidr(cidr)?;
            if !interface.addresses.iter().any(|current| {
                current.family == "inet"
                    && current.address == address.to_string()
                    && current.prefix_len == prefix
            }) {
                return Ok(false);
            }
        }
        let route_matches = |destination: &str, gateway: Option<&str>, table: Option<u32>| {
            routes.iter().any(|route| {
                route.get("destination").and_then(|v| v.as_str()) == Some(destination)
                    && route.get("gateway").and_then(|v| v.as_str()) == gateway
                    && table.is_none_or(|expected| {
                        route.get("table").and_then(|v| v.as_u64()) == Some(u64::from(expected))
                    })
            })
        };
        if !route_matches("0.0.0.0/0", Some(&attach.gateway), None) {
            return Ok(false);
        }
        for route in &attach.routes {
            if !route_matches(&route.destination, route.gateway.as_deref(), route.table) {
                return Ok(false);
            }
        }
        Ok(true)
    }

    async fn verify_attachment(&self, desired: &AttachmentActionConfig) -> Result<bool> {
        if !self.ovs_attachment_ready(&desired.port_attach).await? {
            return Ok(false);
        }
        let pid = super::incus::IncusPlugin::resolve_instance_pid(&desired.container_name).await?;
        self.namespace_attachment_ready(pid, desired.loopback_required, &desired.port_attach)
            .await
    }

    async fn apply_attachment(&self, desired: &AttachmentActionConfig) -> Result<Vec<String>> {
        let initial_pid =
            super::incus::IncusPlugin::resolve_instance_pid(&desired.container_name).await?;
        let mut changes = Vec::new();
        if desired.loopback_required {
            op_network::rtnetlink::set_link_state_in_netns(initial_pid, "lo", true).await?;
        }
        changes.extend(self.ensure_ovs_attachment(&desired.port_attach).await?);

        let move_pid =
            super::incus::IncusPlugin::resolve_instance_pid(&desired.container_name).await?;
        if move_pid != initial_pid {
            anyhow::bail!(
                "Incus instance '{}' restarted during attachment (PID {} -> {}); retry",
                desired.container_name,
                initial_pid,
                move_pid
            );
        }

        let host_interfaces = op_network::rtnetlink::list_interfaces().await?;
        if host_interfaces
            .iter()
            .any(|interface| interface.name == desired.port_attach.port_name)
        {
            op_network::rtnetlink::move_link_to_netns(&desired.port_attach.port_name, move_pid)
                .await?;
            changes.push(format!(
                "moved {} into {} netns PID {}",
                desired.port_attach.port_name, desired.container_name, move_pid
            ));
        }

        let configure_pid =
            super::incus::IncusPlugin::resolve_instance_pid(&desired.container_name).await?;
        if configure_pid != move_pid {
            anyhow::bail!(
                "Incus instance '{}' restarted after link move (PID {} -> {}); retry",
                desired.container_name,
                move_pid,
                configure_pid
            );
        }

        for cidr in &desired.port_attach.ip_addrs {
            let (address, prefix) = op_network::rtnetlink::parse_ipv4_cidr(cidr)?;
            if let Err(error) = op_network::rtnetlink::add_ipv4_address_in_netns(
                configure_pid,
                &desired.port_attach.port_name,
                &address.to_string(),
                prefix,
            )
            .await
            {
                if !Self::already_exists(&error) {
                    return Err(error).with_context(|| format!("assign {cidr}"));
                }
            }
        }
        op_network::rtnetlink::set_link_state_in_netns(
            configure_pid,
            &desired.port_attach.port_name,
            true,
        )
        .await?;
        if let Err(error) = op_network::rtnetlink::add_default_route_in_netns(
            configure_pid,
            &desired.port_attach.port_name,
            &desired.port_attach.gateway,
        )
        .await
        {
            if !Self::already_exists(&error) {
                return Err(error).context("add namespace default route");
            }
        }
        for route in &desired.port_attach.routes {
            if let Err(error) = op_network::rtnetlink::add_ipv4_route_in_netns(
                configure_pid,
                &route.destination,
                route.gateway.as_deref(),
                &desired.port_attach.port_name,
                route.table,
            )
            .await
            {
                if !Self::already_exists(&error) {
                    return Err(error)
                        .with_context(|| format!("add namespace route {}", route.destination));
                }
            }
        }

        if !self.verify_attachment(desired).await? {
            anyhow::bail!(
                "attachment verification failed for {}/{}",
                desired.container_name,
                desired.port_attach.port_name
            );
        }
        changes.push(format!(
            "verified {}/{} at current PID {}",
            desired.container_name, desired.port_attach.port_name, configure_pid
        ));
        Ok(changes)
    }
}

