/// Resolve an exact instance name, accepting a single legacy spelling that
/// differs only by ASCII case. This keeps reconciliation usable during the
/// one-time `NetMaker` -> `netmaker` migration without making ambiguous
/// instance selection possible.
async fn resolve_instance_name(name: &str) -> Result<String> {
    let exact_path = format!("/1.0/instances/{name}/state");
    if Self::incus_api_call("GET", &exact_path, None).await.is_ok() {
        return Ok(name.to_string());
    }

    let mut raw = Self::incus_api_call("GET", "/1.0/instances?recursion=1", None)
        .await
        .with_context(|| format!("list Incus instances while resolving '{name}'"))?;
    let instances: simd_json::OwnedValue = simd_json::from_slice(&mut raw)
        .with_context(|| format!("parse Incus instance list while resolving '{name}'"))?;
    let matches: Vec<String> = instances
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(|instance| instance.get("name").and_then(|value| value.as_str()))
        .filter(|candidate| candidate.eq_ignore_ascii_case(name))
        .map(str::to_string)
        .collect();
    match matches.as_slice() {
        [resolved] => Ok(resolved.clone()),
        [] => anyhow::bail!("Incus instance '{name}' was not found"),
        _ => anyhow::bail!(
            "Incus instance name '{name}' is ambiguous under case-insensitive matching: {}",
            matches.join(", ")
        ),
    }
}

