    let pid = state
        .get("pid")
        .and_then(|value| value.as_u64())
        .ok_or_else(|| anyhow::anyhow!("running Incus instance '{resolved}' has no init PID"))?;
    u32::try_from(pid).with_context(|| format!("Incus PID {pid} does not fit in u32"))
}

/// Create a non-stateful rollback snapshot through the native Incus API.
pub async fn create_snapshot(name: &str, snapshot_name: &str) -> Result<()> {
    let body = simd_json::to_string(&simd_json::json!({
        "name": snapshot_name,
        "stateful": false
    }))?;
    Self::incus_api_call(
        "POST",
        &format!("/1.0/instances/{name}/snapshots"),
        Some(&body),
    )
    .await
    .with_context(|| format!("create Incus snapshot '{name}/{snapshot_name}'"))?;
    Ok(())
}

/// Start or stop an instance through the native Incus state endpoint.
pub async fn set_instance_running(name: &str, running: bool, force: bool) -> Result<()> {
    let body = if running {
        simd_json::json!({ "action": "start" })
    } else {
        simd_json::json!({ "action": "stop", "force": force, "timeout": 30 })
    };
    let body = simd_json::to_string(&body)?;
    Self::incus_api_call(
        "PUT",
        &format!("/1.0/instances/{name}/state"),
        Some(&body),
    )
    .await
    .with_context(|| {
        format!(
            "{} Incus instance '{name}'",
            if running { "start" } else { "stop" }
        )
    })?;
    Ok(())
}

/// Rename a stopped instance through the native Incus API.
pub async fn rename_instance(name: &str, new_name: &str) -> Result<()> {
    let body = simd_json::to_string(&simd_json::json!({
        "name": new_name,
        "migration": false,
        "live": false
    }))?;
    Self::incus_api_call("POST", &format!("/1.0/instances/{name}"), Some(&body))
        .await
        .with_context(|| format!("rename Incus instance '{name}' to '{new_name}'"))?;
    Ok(())
}

/// Set or unset one instance config key without taking ownership of any
/// unrelated configuration.
pub async fn set_instance_config(
    name: &str,
    key: &str,
    value: Option<&str>,
) -> Result<()> {
    let mut data = Self::incus_get_instance(name).await?;
    let config = data
        .get_mut("config")
        .and_then(|value| value.as_object_mut())
        .context("Incus instance config is not an object")?;
    match value {
        Some(value) => {
            config.insert(key.to_string(), simd_json::json!(value));
        }
        None => {
            config.remove(key);
        }
    }
    Self::incus_update_instance(name, data)
        .await
        .with_context(|| format!("update Incus config key '{key}' on '{name}'"))
}

/// Add or replace exactly one local Incus device. No unrelated device is
/// removed or rewritten.
pub async fn reconcile_device(
    instance_name: &str,
    device_name: &str,
    device: &Device,
) -> Result<Vec<String>> {
    let data = Self::incus_get_instance(instance_name).await?;
    let current = data
        .get("devices")
        .and_then(|devices| devices.get(device_name))
        .cloned()
        .map(simd_json::serde::from_owned_value::<BTreeMap<String, String>>)
        .transpose()
        .context("parse current Incus device")?;
    let desired = device.to_incus_map();
    if current.as_ref() == Some(&desired) {
        return Ok(Vec::new());
    }
    if current.is_some() {
        Self::run_incus_command(&[
            "config",
            "device",
            "remove",
            instance_name,
            device_name,
        ])
        .await?;
    }
    let device_type = desired
        .get("type")
        .context("Incus device definition is missing required 'type'")?;
    let mut args = vec![
        "config".to_string(),
        "device".to_string(),
        "add".to_string(),
        instance_name.to_string(),
        device_name.to_string(),
        device_type.clone(),
    ];
    for (key, value) in &desired {
        if key != "type" {
            args.push(format!("{key}={value}"));
        }
    }
    let refs: Vec<&str> = args.iter().map(String::as_str).collect();
    Self::run_incus_command(&refs).await?;
    Ok(vec![format!(
        "Configured device '{device_name}' on '{instance_name}'"
    )])
}

/// Remove exactly one local Incus device if present.
pub async fn remove_device(instance_name: &str, device_name: &str) -> Result<Vec<String>> {
    let data = Self::incus_get_instance(instance_name).await?;
    let present = data
        .get("devices")
        .and_then(|devices| devices.get(device_name))
        .is_some();
    if !present {
        return Ok(Vec::new());
    }
    Self::run_incus_command(&[
        "config",
        "device",
        "remove",
        instance_name,
        device_name,
    ])
    .await?;
    Ok(vec![format!(
        "Removed device '{device_name}' from '{instance_name}'"
    )])
}

