    #[test]
    fn migration_methods_are_exposed_by_schema() {
        let schema = incus_schema();
        for method in [
            "snapshot_instance",
            "restore_snapshot",
            "start_instance",
            "stop_instance",
            "rename_instance",
            "set_instance_config",
            "add_device",
            "remove_device",
            "update_device",
        ] {
            assert!(schema.methods.contains_key(method), "missing {method}");
        }
    }

    #[test]
    fn native_migration_method_outputs_match_their_domain_contracts() {
        let schema = incus_schema();
        let cases: &[(&str, &[&str])] = &[
            ("snapshot_instance", &["instance_name", "snapshot_name"]),
            (
                "restore_snapshot",
                &["instance_name", "restored", "snapshot_name"],
            ),
            ("start_instance", &["name", "running"]),
            ("stop_instance", &["name", "running"]),
            ("restart_instance", &["name", "running"]),
            ("rename_instance", &["name", "previous_name"]),
            ("set_instance_config", &["key", "name", "set"]),
            (
                "add_device",
                &["changes", "device_name", "instance_name"],
            ),
            (
                "remove_device",
                &["changes", "device_name", "instance_name"],
            ),
            (
                "update_device",
                &["changes", "device_name", "instance_name"],
            ),
        ];

        for (method, expected) in cases {
            let returns = schema.methods[*method]
                .returns
                .as_ref()
                .unwrap_or_else(|| panic!("{method} has no output schema"));
            let properties = returns
                .get("properties")
                .and_then(Value::as_object)
                .unwrap_or_else(|| panic!("{method} output is not an object schema"));
            let actual = properties.keys().map(String::as_str).collect::<Vec<_>>();
            assert_eq!(actual, *expected, "wrong output fields for {method}");
        }
    }
}

